/* ÇEVİRİ sq · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("sq","olay",{
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Paqja e Muratit II me Bizantin — Bizanti pranoi sërish të paguante haraç", "6474d704"], "d": ["Murati II, që në 1422 rrethoi Stambollin kundër Bizantit që mbështeste Mustafanë e Rremë, më 22 shkurt 1424 nënshkroi traktat paqeje me perandorin bizantin. Bizanti me këtë traktat pranoi sërish t'u paguante osmanëve haraç dhe t'u kthente vendet që kishte marrë pas 1402-s në brigjet e Marmarasë, Egjeut dhe Detit të Zi, përveç kështjellave të Silivrisë dhe Terkosit; kështu haraçi vjetor, nga i cili ishte çliruar me traktatin e 1403-s me Emir Sulejmanin, u rikthye. Bizanti e vazhdoi këtë gjendje deri në pushtimin e Stambollit në 1453.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["Kështjellat e Bajburtit dhe Kigit u morën në dorëzim nga safevidët — Erzinxhani dhe Bajburti iu dhanë Bijikli Mehmed Beut", "2c7fd65e"], "d": ["Ndërsa Sulltan Selimi Javuz, i kthyer nga Tabrizi pas fitores së Çalldiranit, ishte në kampin ushtarak, erdhën lajmet se kështjellat e Bajburtit dhe Kigit ishin marrë në dorëzim. Sanxhakbeu i Trapezundës Bijikli Mehmed Beu dhe sanxhakbeu i Janinës Mustafa Beu morën në tetor 1514 Bajburtin, që e mbronte Kara Maksud-i Sultani, nga emirët e Shah Ismailit. Erzinxhani, që hyri pa luftë nën sundimin osman, bashkë me Bajburtin më 23 tetor 1514 iu dha si bejlerbejllëk Bijikli Mehmed Beut dhe Bajburti u bë qendër sanxhaku.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Sulltan Selimi Javuz u kthye nga fushata e Tabrizit në Amasja dhe kaloi dimrin atje", "49d51f94"], "d": ["Sulltan Selimi Javuz, që qëndroi nëntë ditë në Tabriz, për shkak të mungesës së ushqimit dhe mosdëshirës së ushtarëve hoqi dorë nga kalimi i dimrit në Iran dhe u kthye përmes Karsit dhe Bajburtit. Padishahu, që kaloi në Niksar festën e Bajramit të Ramazanit, arriti në Amasja dhe kaloi dimrin këtu. Synonte të marshonte sërish vitin pasardhës kundër safevidëve; në Amasja filloi presioni i jeniçerëve për t'u kthyer në Stamboll dhe fushata vazhdoi në pranverën e 1515-s me pushtimin e Kemahut.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["Vllahia, Moldavia dhe Transilvania u ngritën së bashku kundër osmanëve", "e71d3ee9"], "d": ["Në mes të 1594-s tri vojvodatet në veri të Danubit — Vllahia, Moldavia dhe Transilvania — vendosën të vepronin bashkë kundër osmanëve. Vojvoda i Moldavisë Aroni Tiran, duke iu bashkuar Lidhjes së Shenjtë të krijuar nga perandori i Austrisë dhe papa Klementi VIII, iu nënshtrua Principatës së Transilvanisë; vojvoda i Vllahisë Mihai Viteazul, i pakënaqur me barrën e rëndë tatimore, iu bashkua lëvizjes. Më 13 nëntor 1594 në Vllahi dhe Moldavi filluan njëkohësisht kryengritje kundër administratës osmane dhe me mbështetjen e Transilvanisë lëvizja u derdh drejt jugut të Danubit, në tokat osmane. Sipas Enciklopedisë Islame të TDV-së, kjo aleancë treshe hapi frontin verior të Luftës së Gjatë Osmano-Habsburge (1593-1606), që vazhdonte në po ato vite.", "30f44add"]},
"OLAYLAR_P0060:1723-01-01:0":{"b": ["Zbarkimi i forcave ruse në Enzeli dhe vendosja në Resht — fillimi i pushtimit të Gilanit", "15f9a0f2"], "d": ["Pas marrjes së Derbendit, një njësi zbarkimi ruse prej një mijë vetash e ardhur nga Astrahani zbriti në gjirin e Enzelit dhe, me thirrjen e guvernatorit të Reshtit që kërkonte ndihmë kundër afganëve, u vendos në qytet. Pjesa tjetër e Gilanit u mor deri në maj 1723. Ndërsa ushtria osmane po atë pranverë hyri në Kaukaz nëpërmjet Tiflisit; dy perandoritë përparonin brenda nga dy skaje të ndryshme të vendit safavid që po shembej.", "f4cbd759"]},
"OLAYLAR_P0060:1725-01-01:0":{"b": ["Pushtimi i Lahixhanit nga forcat ruse — pika më lindore në Gilan", "3d874b31"], "d": ["Rusët nuk arritën të kalonin përtej Lahixhanit në Gilan; qyteti u pushtua në vitin 1725. Mazenderani dhe Esterabadi, të lëna me Traktatin e Petersburgut, kurrë nuk kaluan faktikisht në duart ruse. Po atë vit ushtria osmane, duke marrë Tebrizin dhe Gjanxhën, e përfundoi pjesën e saj në Azerbajxhan.", "a350db52"]},
"OLAYLAR_P0060:1732-09-02:0":{"b": ["Zbrazja e Gilanit dhe Talishit nga forcat ruse — Levashovi kaloi Kurën", "9503be07"], "d": ["Ndërsa po mbaronte afati i dorëzimit të Traktatit të Reshtit, korpusi rus i Gilanit u tërhoq nga Gilani e Talishi dhe kaloi në veri të lumit Kura; vetëm në Gilan midis janarit dhe marsit 1732 më shumë se një mijë ushtarë kishin vdekur nga sëmundjet. Prania ruse në bregdet tani përbëhej vetëm nga veriu i Kurës, Bakuja dhe Derbendi; edhe këto u kthyen me Traktatin e Gjanxhës të vitit 1735.", "ec20f6a3"]},
"OLAYLAR_P0063:1724-09-11:0":{"b": ["Asgjësimi i batalionit rus në Saljan — njësitë e Tahmasbit hynë në grykën e Kurës", "f0b425c9"], "d": ["Pas marrjes së Bakusë, oficerët e batalionit rus të vendosur në grykën e Kurës u vranë në një gosti që dha naibi i Saljanit; njësia e mbetur u tërhoq në Baku dhe në Saljan hyri një njësi prej rreth katër mijë vetash e Tahmasbit II. Rusët mundën të ktheheshin në rajon vetëm disa vjet më vonë, duke emëruar vetë naibin. Kjo është një nga rastet e rralla gjatë periudhës së pushtimit kur rusët u zmbrapsën me armë brenda Iranit.", "375630fa"]},
"OLAYLAR_P0063:1734-05-31:0":{"b": ["Kërcënimi i Nadirit ndaj të dërguarit rus Golicin: nëse nuk dorëzohen provincat e Kaspikut dhe Derbendi, do të merret vesh me osmanët", "f8fec4a7"], "d": ["Nadiri, që e mundi ushtrinë osmane para Jerevanit, e refuzoi ofertën ruse për ndihmë dhe njoftoi se, nëse Rusia nuk i kthente menjëherë provincat bregdetare të Kaspikut bashkë me Derbendin përtej Traktatit të Reshtit, do të bënte paqe të veçantë me osmanët. Petersburgu, në prag të një lufte të re me osmanët, bëri hap prapa që të mos e shtynte Iranin në anën tjetër.", "89b8c85e"]},
"OLAYLAR_P0063:1734-11-09:0":{"b": ["Urdhri rus për tërheqje — do të zbrazen Bakuja, Nizovaja dhe të gjitha pozicionet nga Kura deri në Derbend", "79a068ef"], "d": ["Urdhri i perandoreshës Anna urdhëronte që forcat ruse fillimisht të tërhiqeshin nga Bakuja dhe kështjella e Nizovajës në Derbend, dhe që edhe Derbendi bashkë me provincat e mbetura të zbraziseshin kur ta lejonte stina. Trysnia e Nadirit kishte dhënë rezultat para traktatit.", "9ad1e7fc"]},
"OLAYLAR_P0063:1735-01-01:0":{"b": ["Dërgimi i forcave të Krimesë në Iran nëpër Kabardi — protesta e Rusisë dhe preteksti i luftës", "e2356781"], "d": ["Forcave të Krimesë iu dha urdhër të kalonin nëpër rajonin e Kabardisë në Kaukaz për të mbështetur ushtrinë osmane në kufirin iranian. Rusia e kundërshtoi urdhrin duke thënë se këto toka i përkisnin asaj. Megjithëse urdhri u tërhoq, rusët e morën si pretekst dhe në pranverën e vitit 1736 sulmuan Azovin; synimi i vërtetë ishte rimarrja e Azovit dhe dalja në Detin e Zi.", "e31f4da0"]},
"OLAYLAR_P0063:1735-05-01:0":{"b": ["Dorëzimi i Bakusë te Irani", "5c6fa266"], "d": ["Sipas kushtit të Traktatit të Gjanxhës për zbrazje brenda dy muajve, komandanti rus de Brilly ia dorëzoi Bakunë Musa Hanit, që erdhi ta merrte në dorëzim.", "68a77e77"]},
"OLAYLAR_P0063:1735-05-08:0":{"b": ["Dorëzimi i Derbendit te Irani — fundi i pushtimit rus trembëdhjetëvjeçar", "ad7b20ab"], "d": ["Çelësat e Derbendit iu dorëzuan palës iraniane; disa njësi ruse qëndruan edhe për pak kohë në qytet. Kështu pushtimi rus i nisur në 1722 mori fund pa asnjë betejë të madhe, për shkak të dëshirës së Rusisë për ta mbajtur Nadirin aleat para një lufte të re me osmanët.", "a72d286a"]},
"OLAYLAR_P0063:1735-07-09:0":{"b": ["Dorëzimi i Gjanxhës te Nadiri", "1b50eb22"], "d": ["Nadiri, që mundi ushtrinë osmane në Arpaçaj, disa javë më vonë mori Gjanxhën, të rrethuar me mure të forta dhe tri hendeqe. Qyteti, që osmanët e kishin marrë në 1725, u bë përsëri i Iranit; Karabaku iu la Iranit me traktatin e vitit 1736.", "03fc4c7d"]},
"OLAYLAR_P0063:1735-08-12:0":{"b": ["Kalimi i Tiflisit në duart e njësive iraniane", "c463de93"], "d": ["Pas forcimit të Nadirit, njësitë iraniane rimorën Tiflisin dhe vunë Ali Mirzën si guvernator të Kartli-Kahetisë. Nadiri e ndryshoi rendin administrativ osman këtu; Kartlin e qeverisi drejtpërdrejt me një guvernator iranian dhe në 1744 ia dha Teimurazit.", "3a18c7c0"]},
"OLAYLAR_P0063:1735-08-23:0":{"b": ["Prishja e kështjellës së Kryqit të Shenjtë — kufiri rus u tërhoq në Terek, u themelua kështjella e Kizlarit", "1bb1117b"], "d": ["Pas traktateve të Reshtit dhe Gjanxhës, kufiri i ri i Rusisë u bë lumi Terek; u vendos të prishej kështjella e Kryqit të Shenjtë mbi Sulak dhe Levashovi njoftoi prishjen në gusht 1735. Po atë vit Levashovi zgjodhi mbi Terek vendin e kështjellës së Kizlarit; kështu prania ruse në bregdetin e Dagestanit, që vazhdonte që nga viti 1722, u tërhoq në veri të Terekut.", "85373e75"]},
"OLAYLAR_P0063:1736-05-02:0":{"b": ["Vendimi për luftë me Rusinë — pas sulmit rus ndaj Azovit", "d19f8545"], "d": ["Kur rusët në dhulkade 1148 (mars 1736) sulmuan kështjellën e Azovit dhe marshuan drejt Orkapisë, qeveria osmane, në divanin që u mblodh, edhe me nxitjen e ambasadorit francez Villeneuve, u detyrua të vendoste luftë kundër Rusisë. Veziri i madh Sejjid Mehmed Pasha u caktua serasker i ushtrisë. Rusia, me marrëveshjen e Gjanxhës të marsit 1735, ishte liruar nga fronti iranian dhe kishte vënë përsëri në rend të ditës synimin e daljes në Detin e Zi.", "a65d5ca0"]},
"OLAYLAR_P0063:1736-06-01:0":{"b": ["Dorëzimi i Orkapisë te Münnich — ushtria ruse hyri në Krime", "af2b2613"], "d": ["Münnich më 16 maj (julian) mbërriti para vijave të Orkapisë dhe në agimin e 20 majit sulmoi vijat; ushtria tatare e zënë në befasi u tërhoq, kështjella e Orit u dorëzua të nesërmen. Ushtria ruse dy ditë më vonë marshoi në brendësi të gadishullit; Orkapia mbeti në duart ruse deri në fund të gushtit.", "3fec9485"]},
"OLAYLAR_P0063:1736-06-19:0":{"b": ["Dorëzimi i kështjellës së Kılburunit te Leontievi", "a0600527"], "d": ["Ndërsa Münnich përparonte në Krime, kolona e Leontievit që ai e kishte veçuar u drejtua nga Kılburuni në grykën e Dnjeprit dhe kështjella u dorëzua. Meqë burimi nuk jep ditën kur forcat ruse u tërhoqën nga kështjella, në hartë nuk tregohet dritare pushtimi.", "c1632ebd"]},
"OLAYLAR_P0063:1736-07-13:0":{"b": ["Rënia e Azovit në duart e rusëve", "004b5ef1"], "d": ["Në fund të sulmit të nisur në mars 1736, kështjella e Azovit në grykën e Donit kaloi në duart e rusëve. Po atë verë rusët kaluan Orkapinë, hynë në Krime, morën Gözleven dhe Kılburunin dhe bënë shkatërrime në Bahçesaraj dhe Akmesxhid. Me paqen e vitit 1739 Azovi i mbeti Rusisë, por fortifikimet u prishën. Burimet ndryshojnë për ditën e rënies: TDV këtë datë e jep bashkë me Gözleven, Orkapinë dhe Kılburunin; burimet ruse thonë 19 qershor (gregorian 30 qershor), një burim tjetër 1 korrik.", "fccaab17"]},
"OLAYLAR_P0063:1736-08-27:0":{"b": ["Münnich shkatërroi vijën e Orkapisë dhe u tërhoq nga Krimea", "84ee7e5c"], "d": ["Münnich, i kthyer nga brendësia e Krimesë në Orkapi, qëndroi këtu pesë javë. Për shkak të mungesës së ushqimit dhe sëmundjeve që u përhapën në ushtri, pasi shkatërroi vijën e fortifikimeve të Perekopit, u tërhoq në Ukrainë; kur rusët ikën, tatarët e rindërtuan vijën.", "d453b2eb"]},
"OLAYLAR_P0063:1737-07-14:0":{"b": ["Austria i shpalli luftë Shtetit Osman — front i dytë përkrah Rusisë", "c27ed99a"], "d": ["Austria, aleate e Rusisë, ndërsa ishte vendosur të bëheshin bisedime paqeje në Nemirov, në qershor 1737 sulmoi tokat osmane nga tri drejtime; shpallja zyrtare e luftës nga perandori mban datën 14 korrik 1737. Seckendorf në korrik mori Nishin, por operacioni austriak në Bosnjë u ndal në gusht në Banja Lluka. Ky front u mbyll me Traktatin e Beogradit të vitit 1739 me humbje për Austrinë.", "7d5518a3"]},
"OLAYLAR_P0063:1737-07-25:0":{"b": ["Pararoja e Lacy-t mori dhe dogji Karasubazarin", "ee36541f"], "d": ["Lacy, që kaloi Sivashin dhe hyri në Krime, më 12 korrik (julian) zmbrapsi sulmin e hanit. Dy ditë më vonë gjenerali Duglas në pararojë shpërndau kampin ushtarak tatar para Karasubazarit, mori qytetin pa qëndresë dhe e dogji. Lacy të nesërmen filloi të tërhiqej.", "ac1fd466"]},
"OLAYLAR_P0063:1737-07-27:0":{"b": ["Rënia e Nishit në duart e Austrisë — operacioni i Seckendorf-it në Serbi", "084a31e8"], "d": ["Në verën e vitit 1737, dega serbe e ushtrisë austriake që hyri në tokat osmane nga tri drejtime, nën komandën e Mareshalit Seckendorf, zbriti nëpër luginën e Moravës në jug dhe mori Nishin. Rënia e kështjellës ishte suksesi i vetëm i madh i luftës në favor të Austrisë; por në tetor të po atij viti bejlerbeu i Rumelisë Qyprilliu-zade Hafiz Ahmed Pasha e rimori Nishin pa luftë.", "5fd4065d"]},
"OLAYLAR_P0063:1737-10-16:0":{"b": ["Rimarrja e Nishit nga Austria", "265e0917"], "d": ["Nishin, që ushtria austriake nën komandën e Seckendorf-it e mori në rebiulevel 1150 (korrik 1737), bejlerbeu i Rumelisë Qyprilliu-zade Hafiz Ahmed Pasha e rimori në tetor të po atij viti. Kjo ishte zhvillimi i dytë, pas Banja Llukës, që e prishi operacionin austriak të vitit 1737.", "2f62abcc"]},
"OLAYLAR_P0063:1738-08-17:0":{"b": ["Marrja e Ada Kalesë nga Austria", "24f58282"], "d": ["Ushtria osmane, që doli në fushatë në pranverën e vitit 1738, mori Mehadien, rrethoi Orshovën dhe Ada Kalenë dhe, duke kaluar Danubin, bëri inkursione drejt Timishoarës. Ada Kaleja u mor më 17 gusht 1738. Pastaj Jegen Mehmed Pasha, që erdhi në Nish, bëri inkursione drejt Beogradit; një vit më vonë erdhën fitorja e Hisarxhikut dhe Traktati i Beogradit.", "9b408b77"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Pushtimi i kështjellës së Ostrovicës në luginën e Unës", "5c6cc91b"], "d": ["Ostrovica, në duart e fisnikëve Frankapan dhe të tjerë kroatë, ndodhej mbi një kurriz të thepisur që lidhte pjesët veriore dhe jugore të luginës së Unës. Në 1523 kaloi nën administratën osmane dhe deri në 1878 pati garnizon osman. Rëndësinë kryesore kështjella e fitoi pas Karlovacit (1699): për shkak të afërsisë me kufirin venecian e austriak u zgjerua dhe u bë qendra e kapetanatit të Ostrovicës së Vjetër; qyteza Kulen Vakuf u ngrit në rrëzë të saj në fillim të shekullit XVIII.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Pushtimi i kështjellave të Udbinës dhe Krbavës — Lika hyn nën administratën osmane", "5fe329d3"], "d": ["Fusha e Krbavës u boshatis në 1524 dhe në Udbinë mbeti vetëm garnizoni i Karlović-it. Karlović në prill 1527 fitoi një fitore të fundit para kështjellës, por në fund të majit Udbina, bashkë me kështjellat Mrsinj dhe Komić, ra në duart e pashait të Bosnjës. Po atë vit krahina e Gospićit iu dha agallarëve Senković. Pas kësaj, Lika dhe Krbava u bënë pjesë e sanxhakut me qendër Obrovacin, që në 1580 mori emrin Kërka.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Kalimi përfundimtar i Drežnikut dhe zhupanatit të tij nën administratën osmane", "6624ad14"], "d": ["Drežniku, që që nga 1323 ishte në duart e Frankapanëve, në 1578 ishte mbajtur përkohësisht nga osmanët. Në 1592 kështjella dhe gjithë zhupanati i Drežnikut hynë përfundimisht nën administratën osmane; po atë vit ra edhe Bihaqi. Drežniku në shekullin XVIII ishte i lidhur me kapetanatin e Ostrožacit.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Marrja e kështjellës së Cetinit nga osmanët", "98815f97"], "d": ["Cetini, që nga mesi i shekullit XVI ishte kështjella kyçe në mbrojtjen e krahinës së Slunjit kundër osmanëve, pas shumë rrethimeve kaloi nën administratën osmane në 1636. Kjo periudhë e parë osmane zgjati dy vjet.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Kthimi i kështjellës së Cetinit në anën habsburge", "690f9f84"], "d": ["Cetini, që në 1636 kaloi në duart osmane, në 1638 u kthye sërish në mbrojtjen kufitare kroato-habsburge dhe mbeti i tillë deri në 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetini bëhet sërish kështjellë osmane", "e1750675"], "d": ["Cetini në 1670 u bë sërish kështjellë osmane dhe në shekullin XVIII u fortifikua rrënjësisht: kështjella mesjetare u rrethua me mure me bastione. Deri në 1790 kështjella mbajti skajin veriperëndimor të kufirit boshnjak.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Humbja e Likës dhe Krbavës — Udbina dhe Gospići kaluan në duart e forcave kufitare habsburge", "01277a38"], "d": ["Në luftën që vazhdoi pas shpartallimit të Vjenës, njësitë kufitare kroate nën komandën e gjeneralit të Karllovacit Herberstein morën Udbinën në 1689; edhe Gospići po atë vit doli nga administrata osmane. Mori fund Lika osmane që zgjati më shumë se 160 vjet, vendet e zbrazura u populluan me popullsi të re kroate dhe Udbina, deri në paqen e Sishtovës (1791), ishte një kështjellë e rëndësishme e mbrojtjes kufitare kundër osmanëve.", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Pushtimi i Drežnikut nga Austria — fronti perëndimor i Luftës së Dubicës", "05d5e5f1"], "d": ["Në luftën osmano-austriake të 1788-1791, forcat habsburge morën Drežnikun në perëndim të Bihaqit. Me nenin 4 të Traktatit të Sishtovës, Drežniku dhe Cetini mbetën nën administratën habsburge dhe nuk iu kthyen më Bosnjës.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Pushtimi i kështjellës së Cetinit nga Austria", "df182480"], "d": ["Në 1790 ushtria habsburge sulmoi Cetinin, Bužimin dhe Velika Kladushën dhe mori Cetinin. Mobilizimi dhe kundërsulmi i shpallur nga guvernatori i Bosnjës nuk e rimorën dot kështjellën; neni 4 i Traktatit të Sishtovës ua la Cetinin Habsburgëve. Luftëtarët kufitarë boshnjakë e rimorën kështjellën me sulme të shkurtra në 1809 dhe 1813.", "fc69baec"]},
"OLAYLAR_P0917KOSU13:1387-01-01:0":{"b": ["Pushtimi i Vodinës (dimri 1386-1387)", "1e542d14"], "d": ["Vodina në perëndim të Vardarit në Maqedoni hyri nën administratën osmane me një pushtim për të cilin kronikat osmane japin vite të ndryshme. Hoxha Sadedini e vendos pushtimin në 1386; TDV e gjen më të përshtatshme të pranohet me gjasë të fortë dimri 1386-1387. Meqë komandanti që bëri pushtimin nuk përmendet hapur te burimi, nuk u shkrua personi.", "0da93b6a"]},
"OLAYLAR_P0917KOSU13:1415-01-01:0":{"b": ["Hyrja e Manisës nën administratën e Mehmet Çelebiut — fundi i degës së Manisës të Saruhanëve", "6d6c7622"], "d": ["Në fund të Periudhës së Interregnumit, vendi i Saruhanit hyri nën administratën e Mehmet Çelebiut dhe dega e Manisës e Saruhanëve (Saruhanoğulları) u zhduk nga historia. TDV e vendos këtë kalim pas vitit 1411 dhe para vitit 1415; administrata osmane mundi të vendosej plotësisht pak para vitit 818 (1415). Prandaj data u shkrua me skajin më të vonë të intervalit.", "4d3e8c85"]},
"OLAYLAR_P0917KOSU13:1427-01-01:0":{"b": ["Kalimi i Giurgiut te Vllahia", "bc5c11f4"], "d": ["Kështjella e Giurgiut (Yergöğü) në bregun e Danubit u rimor nga vllehët në 1427. Kështjella ishte njëra nga pikat e para të osmanëve në bregun verior të Danubit dhe mbeti te Vllahia për më shumë se njëzet vjet.", "91dc683d"]},
"OLAYLAR_P0917KOSU13:1450-01-01:0":{"b": ["Hyrja përsëri e Giurgiut nën kontrollin osman (853/1449-50)", "c9ad1b89"], "d": ["Kështjella e Giurgiut, që vllehët e rimorën në 1427, në vitin 853 hyri përsëri nën kontrollin osman. Meqë viti hixhri shtrihet nga shkurti 1449 deri në shkurt 1450, data u shkrua me fillimin e vitit 1450 që bie brenda intervalit. Që atëherë kështjella u bë një serhat osman që mbronte kalimin e Danubit.", "15b80685"]},
"OLAYLAR_P0917KOSU13:1516-10-01:0":{"b": ["Hyrja e Jerusalemit dhe qyteteve të Palestinës nën administratën osmane", "7ac58e9d"], "d": ["Pas fitores së Mexh Dabikut, me mbërritjen e Selimit I Javuz në Damask më 27 shtator, qytetet e Sirisë dhe Palestinës kaluan njëri pas tjetrit nën administratën osmane. TDV tregon se Nablusi hyri nën administratën osmane në vjeshtën e 1516, ndërsa Jerusalemi ndoshta në tetor 1516, para mbërritjes së padishahut. Padishahu erdhi në Jerusalem vetëm pas betejës së Gazës, më 29 dhjetor 1516.", "7680d172"]},
"OLAYLAR_P0917KOSU13:1532-01-01:0":{"b": ["Bitlisi kaloi nën mbrojtjen safavide — Ulama dhe Fil Pasha hoqën rrethimin", "2d0610f6"], "d": ["Kur Tekelü Ulama u strehua te osmanët dhe u caktua bejlerbej mbi tokat e Bitlisit, sundimtari i Bitlisit Sheref Hani, vartës i osmanëve, u strehua te safavidët. Ulama dhe bejlerbeu i Dijarbekirit Fil Pasha në vitin 938 e rrethuan kështjellën; kështjella qëndroi tre muaj dhe forcat osmane, kur mësuan se po afrohej Shah Tahmasbi, e hoqën rrethimin. Shahu ia bashkoi Sheref Hanit Bitlisin bashkë me rrethinat e Ahlatit, Mushit dhe Hınısit.", "8b605ee5"]},
"OLAYLAR_P0917KOSU13:1534-01-01:0":{"b": ["Bitlisi, nëpërmjet Ulama Pashës, iu bashkua përfundimisht Shtetit Osman", "7631002a"], "d": ["Tekelü Ulama, rrethimi i parë i të cilit mbeti pa rezultat, në vitin 940 (1533) vrau sundimtarin e Bitlisit Sheref Hanin dhe në 1534 ia bashkoi përfundimisht Bitlisin tokave osmane. Djali i Sheref Hanit, Shemsedin Beu, pasi Bitlisi iu dha Ulamasë, u strehua te safavidët me fisin Rojeki. Sovraniteti osman mbi Bitlisin u njoh edhe nga safavidët me Traktatin e Amasjes të vitit 1555.", "3d1f3e99"]},
"OLAYLAR_P0917KOSU13:1565-01-01:0":{"b": ["Marrja e kështjellës së Krupës nga osmanët", "7a786bf3"], "d": ["Kështjella e Krupës në bregun e djathtë të Unës kaloi në duart e osmanëve në 1565. Në dy shekujt pasues kështjella mbeti te osmanët përballë rrethimeve austriake (1581, 1690, 1692, 1716) dhe u bë pjesë e vijës kufitare të Unës midis Bihaqit dhe Novit.", "e7a52e35"]},
"OLAYLAR_P0917KOSU13:1578-08-24:0":{"b": ["Marrja e Tiflisit pa luftë — nënshtrimi i Kahetit dhe Imeretit", "b1563ee6"], "d": ["Pas fitores së Çëlldërit, ushtria osmane nën komandën e Lala Mustafa Pashës, që përparonte, mbërriti në Tiflis më 24 gusht dhe e mori pa luftë kështjellën e zbrazur. Pas pushtimit të Tiflisit, sundimtarët e Imeretit dhe Kahetit ua shprehën osmanëve nënshtrimin.", "41a9cb07"]},
"OLAYLAR_P0917KOSU13:1588-09-01:0":{"b": ["Nënshtrimi i sundimtarit të Karaxhadagut (Aharit) Shahverdi Han te Xhafer Pasha — hyrja e Merendit nën administratën osmane", "fe55fb37"], "d": ["Bejlerbeu i Tabrizit Xhafer Pasha në 1588 e shtriu pushtetin e tij në Merend; sundimtari i Karaxhadagut Shahverdi Han u nënshtrua dhe dërgoi djalin e tij në Tabriz. Burimet japin vetëm vitin; dita u lidh me fushatën e Gjanxhës të po atij viti.", "9a1a0cee"]},
"OLAYLAR_P0917KOSU13:1589-01-01:0":{"b": ["Xhigala-zade Sinan Pasha mori Nihavendin dhe ndërtoi kështjellë — nënshtrimi i Luristanit", "1a6a0329"], "d": ["Valiu i Bagdadit Xhigala-zade Sinan Pasha në fund të vitit 1588 mori Nihavendin dhe ndërtoi aty një kështjellë; sundimtari i Luristanit Shahverdi iu nënshtrua osmanëve. Burimet nuk japin ditën; data është në nivel viti.", "89a4eefd"]},
"OLAYLAR_P0917KOSU13:1722-11-01:0":{"b": ["Njohja nga osmanët e sundimit të Haxhi Davudit mbi Shirvanin", "8e7b0476"], "d": ["Osmanët në nëntor 1722, ndërsa u jepnin forcave ruse ultimatum për t'u tërhequr nga rajoni, njohën sundimin e Haxhi Davudit mbi Shirvanin. Kështu Haxhi Davudi, si hani i Krimesë, u bë sundimtar vasal i varur nga osmanët.", "6b466aaf"]},
"OLAYLAR_P0917KOSU13:1723-08-06:0":{"b": ["Forcat ruse morën Bakunë", "482170dc"], "d": ["Në vitin e dytë të fushatës së Kaspikut të Pjetrit I, njësia e gjeneralit Matjushkin erdhi nga deti dhe mori Bakunë. Qyteti mbeti me garnizon rus deri sa me Traktatin e Gjanxhës në 1735 iu kthye Iranit. Zëri i TDV-së për Bakunë e vendos kthimin në 1734; burimet ruse dhe iraniane japin Traktatin e Gjanxhës të vitit 1735.", "29dc4fb3"]},
"OLAYLAR_P0917KOSU13:1723-11-10:0":{"b": ["Dorëzimi i Sanandazhit (Sinesë), qendrës së Erdelanit", "83b23183"], "d": ["Pas marrjes së Kermanshahut, beu baban Hane Mehmed Pasha, i dërguar kundër Erdelanit, mori në dorëzim qendrën e ejaletit, Sanandazhin; livatë Mihriban (Marivan), Bane dhe Sakiz iu bashkuan gjithashtu ejaletit osman të Erdelanit. Në 1727 për ejaletin u mbajt një defter tahrir osman i hollësishëm.", "e4060148"]},
"OLAYLAR_P0917KOSU13:1724-01-01:0":{"b": ["Kalimi i Urmisë dhe Salmasit nën administratën osmane", "1e25828f"], "d": ["Në vitet kur Shteti Safavid po shpërbëhej nga pushtimi afgan, Urmia hyri edhe një herë nën sundimin osman. Në 1728 u mbajt defter tahrir osman për livanë e Urmisë dhe Salmasit të varur prej saj. Në ofensivën e Nadirit të 1729-1730 rajoni doli nga duart; Hekimoglu Ali Pasha e rimori Urminë në 1731.", "505c034f"]},
"OLAYLAR_P0917KOSU13:1725-09-09:0":{"b": ["Marrja e Ardabilit", "917ebe96"], "d": ["Pas Tabrizit, forcat e Qyprilliu-zade Abdullah Pashës hynë në Ardabil, qendrën shpirtërore të safavidëve. Në 1728 qyteti, së bashku me nahijet Serab dhe Mijane, u regjistrua si livaja osmane e Ardabilit; edhe Halhali fqinj u shënua në defter si liva e veçantë. Nadiri e rimori Ardabilin në 1730.", "1fe99397"]},
"OLAYLAR_P0917KOSU13:1731-11-15:0":{"b": ["Hekimoglu Ali Pasha rimori Tabrizin", "fda463ac"], "d": ["Tabrizin, që në 1730 kishte kaluar në duart e safavidëve, Hekimoglu Ali Pasha e rimori më 15 nëntor 1731; në po atë operacion ishte marrë edhe Urmia. Por me traktatin e 10 janarit 1732 Tabrizi iu la Iranit. Atlasi e konsideron edhe Koturin, që ndjek zinxhirin e Hojit, si të kaluar po atë ditë nga safavidët te osmanët (TDV hoy; dita e veçantë për Koturin mungon te burimi — përafrim i deklaruar).", "9847bdc5"]},
"OLAYLAR_P0917KOSU13:1735-10-03:0":{"b": ["Dorëzimi i Jerevanit te Nadir Hani", "371ef64b"], "d": ["Pas disfatës së Arpaçajt (Baghavardit), Nadir Hani, që mori Gjanxhën më 9 korrik dhe Tiflisin më 12 gusht, mori edhe Jerevanin. Nahijet Karpi (Üçkilise), Sherur dhe Maku, bashkë me qendrën e ejaletit, kaluan te Irani.", "d2c03da0"]},
"OLAYLAR_P0917KOSU13:1770-09-01:0":{"b": ["Dorëzimi i kështjellës së Kilisë te Repnini", "e894b7d0"], "d": ["Pas disfatës së Kartallit, kolona e Repninit që zbriti në grykën e Danubit mbërriti para Kilisë më 10 gusht (julian). Pas zjarrit të baterive të thyerjes dhe një mbrojtjeje dhjetëditore, garnizoni e dorëzoi kështjellën me kusht që të dilte lirisht me armët e veta dhe popullin me mallrat. Kilia iu kthye osmanëve me Traktatin e Küçük Kajnarxhasë (1774).", "fb66a9e9"]},
"OLAYLAR_P0917KOSU13:1770-10-09:0":{"b": ["Në grykën e Dnjestrit ra kështjella e Akkermanit", "018c420b"], "d": ["Pak kohë pas rënies së Benderit, edhe Akkermani në grykën e Dnjestrit kaloi në duart e forcave ruse. Kështjella iu kthye osmanëve me Traktatin e Küçük Kajnarxhasë (1774).", "38e48332"]},
"OLAYLAR_P0917KOSU13:1788-09-01:0":{"b": ["Pushtimi i Hotinit nga forcat austro-ruse", "a6c18567"], "d": ["Në luftën e nisur në 1787, forcat e përbashkëta të Austrisë dhe Rusisë rrethuan Hotinin dhe kështjella u mor nga këto forca në shtator 1788. Sipas Traktatit të Zishtovës, Austria e mbajti kështjellën në ruajtje deri në përfundimin e paqes me Rusinë; Hotini iu kthye osmanëve me Traktatin e Jashit të vitit 1792.", "59f8979f"]},
"OLAYLAR_P0917KOSU13:1789-11-01:0":{"b": ["Pushtimi i Bukureshtit nga ushtria austriake (Coburg)", "ec890b9a"], "d": ["Pas disfatës së Rimnikut, ushtria austriake në fillim të nëntorit 1789 pushtoi Bukureshtin, qendrën e Vllahisë. Qyteti iu kthye palës osmane me Traktatin e Zishtovës të 4 gushtit 1791.", "8c031b96"]},
"OLAYLAR_P0917KOSU13:1789-11-14:0":{"b": ["Dorëzimi i kështjellës së Benderit te Potemkini", "a661bafa"], "d": ["Në luftën osmano-ruse 1787-1792, kështjella e Benderit mbi Dnjestër iu dorëzua ushtrisë ruse nën komandën e Potemkinit. Kështjella iu kthye osmanëve me Traktatin e Jashit të vitit 1792.", "b150e1c5"]},
"OLAYLAR_P0917KOSU13:1790-10-24:0":{"b": ["Dorëzimi i kështjellës së Kilisë te rusët", "5e88acfe"], "d": ["Në fushatën e vitit 1790, kështjella e Kilisë në grykën e Danubit u rrethua më 4 tetor (kalendari i vjetër) dhe nëntë ditë më vonë iu dorëzua gjeneralit Gudoviç. Kështjella iu kthye osmanëve me Traktatin e Jashit të vitit 1792.", "45089b90"]},
"OLAYLAR_P0917KOSU13:1809-09-26:0":{"b": ["Dorëzimi i kështjellës së Izmailit te gjenerali Zass", "dc74c6d0"], "d": ["Gjatë luftës osmano-ruse 1806-1812, kështjella e Izmailit mbi Danub iu dorëzua gjeneralit Zass. Kështjella, me Traktatin e Bukureshtit të vitit 1812, iu la Rusisë bashkë me Besarabinë.", "4d43c35c"]},
"OLAYLAR_P0917TARAF:1892-01-01:0":{"b": ["Rregullimi i dytë franko-osman — kufiri Tunizi-Tripoli u shtri deri në Gadames", "94885487"], "d": ["Një rregullim i dytë franko-osman e përcaktoi kufirin midis Tunizisë dhe vilajetit të Tripolit më me hollësi se i mëparshmi dhe, në brendësi, deri në Gadames. Dokumenti kryesor që vizaton kufirin e sotëm është Konventa e Tripolit, që do të nënshkruhet tetëmbëdhjetë vjet më vonë.", "b9df9291"]},
"OLAYLAR_P0917TARAF:1906-10-01:0":{"b": ["Marrëveshja e Rafahut — u përshkrua vija Rafah-Taba midis Shtetit Osman dhe Hidivatit të Egjiptit", "f10d25c6"], "d": ["Pas krizës Akaba-Taba të vitit 1906, komisarët osmanë dhe të hidivit u morën vesh në Rafah për një vijë ndarëse administrative; vija shtrihej nga Ras Taba në Gjirin e Akabës deri në mesin e dy shtyllave në Rafah. Delegacioni i përzier midis fundit të atij viti dhe shkurtit të vitit pasues ngriti përgjatë vijës nëntëdhjetë e një shtylla muri. Kjo vijë është kufiri i sotëm Egjipt-Izrael dhe Egjipt-Gaza.", "28a925f5"]},
"OLAYLAR_P0917TARAF:1909-04-19:0":{"b": ["Protokolli turko-bullgar në Stamboll — Shteti Osman njohu pavarësinë e Bullgarisë", "97302dc1"], "d": ["Me protokollin e nënshkruar në Stamboll me ndërmjetësimin e Rusisë, Shteti Osman njohu zyrtarisht pavarësinë e Bullgarisë, të shpallur në mënyrë të njëanshme gjashtë muaj më parë. Kështu kufiri i vjetër osmano-bullgar në Strandzhë u bë edhe juridikisht vija midis dy shteteve të pavarura; ky sektor edhe sot është pjesë e kufirit Turqi-Bullgari.", "393405ba"]},
"OLAYLAR_P0917TARAF:1910-05-19:0":{"b": ["Konventa e Tripolit — kufiri midis Tunizisë dhe vilajetit të Tripolit u vizatua nga Ras Ajdiri në Gadames", "9ca9e95a"], "d": ["Konventa e nënshkruar në Tripoli midis Francës dhe Shtetit Osman përshkroi kufirin midis Tunizisë dhe vilajetit të Tripolit nga Ras Ajdiri në bregun e Mesdheut deri në jug të Gadamesit. Komisioni i përzier në 1910-1911 e shënoi vijën me më shumë se dyqind gurë; vija edhe sot është kufiri Libi-Tunizi. Dy vjet më vonë, me Traktatin e Ouchy-së, ky kufi kaloi nga osmanët te Italia.", "74a4bc3f"]},
"OLAYLAR_P0917TARAF:1913-11-17:0":{"b": ["Protokolli i Stambollit — caktimi i kufirit turko-iranian", "daa100b9"], "d": ["Përfaqësuesit osmanë dhe iranianë, nën mbikëqyrjen e ambasadorëve britanik dhe rus, nënshkruan në Stamboll protokollin e caktimit të kufirit turko-iranian, bazuar në Traktatin e Erzurumit të vitit 1847. Komisioni i përzier deri në tetor të vitit pasues e shënoi në terren vijën, përveç një pjese të shkurtër rreth Koturit. Kjo vijë, që në 1923 mbeti kufiri Turqi-Iran, u ndryshua në tri pjesë në vitet 1932 dhe 1937.", "4bb44a7b"]},
"OLAYLAR_P0917TARAF:1915-09-06:0":{"b": ["Konventa e Sofjes — korrigjimi i kufirit osmano-bullgar", "42026201"], "d": ["Konventa e nënshkruar në Sofje pak para se Bullgaria të hynte në luftë në krah të osmanëve korrigjoi kufirin osmano-bullgar të caktuar nga Traktati i Stambollit i vitit 1913. Pjesa e Trakisë Lindore e vijës u shënua përsëri nga komisioni i Neuillyt në 1921 dhe u konfirmua në Lozanë.", "b259b598"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilexhiku përmendet për herë të parë — kufiri me Bizantin fillonte në Bilexhik", "7b69f743"], "d": ["Në ngjarjet e vitit 683 që përcjell Neshriu, Bilexhiku del si vendi ku fillonte kufiri mes bejlikut kufitar të Osman Beut dhe Bizantit. Kjo është përmendja e parë e njohur historike e vendbanimit; nuk është themelimi i tij.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Në Burdur monedhë në emër të Gazan Hanit — dëshmia e parë e njohur e qytetit", "01974ddc"], "d": ["Hamidogullarët, nën presionin ilhanid, në vitin 699 u detyruan të presin në Burdur monedhë në emër të Gazan Hanit. Kjo monedhë është dëshmia e parë e shkruar/e datuar e Burdurit.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Çorumi përmendet në vendin e Eretnas — dëshmia e parë e njohur e qytetit", "bf7bd67f"], "d": ["Me vdekjen e Eretna Beut në muharrem 753, ndër qytetet nën sundimin e tij numërohet edhe Çorumi. Themelimi i qytetit nuk dihet; kjo përmendje është dëshmia më e hershme e datuar që mund të gjendej.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Braila përmendet për herë të parë — dokumenti i privilegjit të Vlaicu Vodës për tregtarët e Brashovit", "0b3517a7"], "d": ["Vojvoda i Vllahisë Vladisllavi u dha tregtarëve të Brashovit një dokument që u njihte lehtësi kur transportonin mallra në rrugën e Brailës. Ky dokument është dëshmia e parë e shkruar e njohur e Brailës; vendi këtu ende nuk përmendet si qytet, por si skaji i rrugës në Danub. Nuk është data e themelimit.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Kishinevi u përmend për herë të parë në dekretin e vojvodës së Moldavisë", "a50799d7"], "d": ["Emri i Kishinevit del për herë të parë në një dekret të vitit 1420 të vojvodës së Moldavisë Aleksandru. Qyteti për një kohë të gjatë mbeti një qytezë e vogël moldave; kur në 1812 bashkë me Besarabinë kaloi te Rusia, u bë qendër province.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Galaci përmendet për herë të parë në një dokument të vojvodës së Moldavisë", "a31af8a2"], "d": ["Vojvoda i Moldavisë Shtefani II i përjashtoi nga taksa doganore dy qerret e Manastirit të Humorit që sillnin peshk nga Galaci. Ky dokument është dëshmia e parë e shkruar e Galacit e njohur me siguri; vendbanimi mund të ketë ekzistuar më parë si fshat peshkatarësh në bregun e Danubit.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["Emri i Mostarit del për herë të parë në një dokument të Dubrovnikut", "a599bc55"], "d": ["Emri i Mostarit del për herë të parë në një dokument të Dubrovnikut të 3 prillit 1452; vendbanimi ishte në tokat e Dukatit të Hercegut. Pushtimi osman është i 1466-68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["Në Sarajevë Xhamia Hyqar — dëshmia më e hershme e datuar e vendbanimit", "ad697a7d"], "d": ["Sanxhakbeu i Bosnjës Is'hak Beu, në vendbanimin e parë mysliman në fushën e Sarajit, ndërtoi për vete një saraj, në emër të Sulltan Mehmetit Fatih Xhaminë Hyqar (Hünkâr Camii) dhe pranë saj një hamam. Xhamia është e datuar 862 (1458); është ndërtesa më e hershme e datuar e njohur në Sarajevë.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Vakëfnameja e Is'hak Beut — bërthama urbane e Sarajevës u la vakëf", "0b364229"], "d": ["Nga vakëfnameja e Is'hak Beut e xhumadelulasë 866 (shkurt 1462) kuptohet se, përveç xhamisë dhe hamamit, u ndërtuan teqeja (zavija), teqeja mevlevie, imareti, një urë mbi Miljackën, hani Kolobara në bregun përballë, bedesteni, karvansaraji dhe dyqane. Dokumenti është themeli vakëfor i qytetit; vendbanimi ekzistonte para tij.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Tatarpazarxhiku regjistrohet për herë të parë në defterin e akinxhinjve", "3b1c839e"], "d": ["Shënimet më të vjetra për qytetin zbresin deri në vitin 877 (1472): një defter akinxhinjsh në Bibliotekën Kombëtare të Sofjes e regjistron vendbanimin.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banja Luka përmendet për herë të parë në një udhëzim të mbretit Vladisllavi II", "0ebc6288"], "d": ["Emri Banja Luka del për herë të parë në një udhëzim të mbretit hungarezo-kroat Vladisllavi II të 6 shkurtit 1494; krahina ishte e lidhur me kurorën hungareze përmes banatit të Jajcës. Pushtimi osman është i dimrit 1527-28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["Popullsia e Basrës përfundon zhvendosjen në vendin e sotëm — Basra e vjetër braktiset", "20f96eac"], "d": ["Populli me kohë kishte filluar të vendosej në Basrën e sotme, që e gjente më të sigurt kundër sulmeve beduine dhe ku furnizohej më lehtë me ujë; kalimi në vendin e ri u përfundua në vitin 900 (1494-95). Basra e vjetër, e themeluar në kohën e halifit Omer, ishte rreth 25 km larg qytetit të sotëm.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Mengli Giraj Hani ndërtoi Sarajin e Hanit në breg të Çürüksu — themeli i Bahçesarajit", "0792497c"], "d": ["Në luginën që ishte zonë verore gjuetie e pushimi e guvernatorëve të Hordhisë së Artë dhe hanëve të parë të Krimesë, Mengli Giraj I ndërtoi në breg të Çürüksu sarajin që sot njihet si Saraji i Hanit dhe hodhi themelin e Bahçesarajit. Qyteti u zhvillua rreth sarajit dhe përgjatë luginës së ngushtë të Çürüksu, nga fundi i shekullit XVI u bë i lulëzuar dhe qendra e Hanatit të Krimesë.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["Kozakët e Zaporizhisë ndërtuan Siçin e parë në ishullin Hortica", "e6ca0dd9"], "d": ["Princi Dmitro Vishnevecki ndërtoi Siçin e parë të Zaporizhisë në ishullin e Horticës së Vogël në Dniepër. Kështjella në 1558 u rrethua dhe u shkatërrua nga tatarët e Krimesë; Siçi më vonë u zhvendos në ishujt më në jug. Termi: «Siçi» (ukrainisht Sich) është kampi qendror i kozakëve të Zaporizhisë në ishujt e Dnieprit, i fortifikuar me trungje dhe hendeqe; është qendra e shtabit, vendi i kuvendit (Rada) dhe i kreut të zgjedhur të ushtrisë (koshovoj), nuk është kryeqytet shteti.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["U ndërtua Siçi i Bazavlukut", "fcd507ae"], "d": ["Pasi tatarët shkatërruan Siçin e Tomakivkës, kozakët e Zaporizhisë ngritën Siçin e ri në ishullin Bazavluk, në vendin ku Dniepri bashkohet me degët Çortomlik, Pidpilna dhe Skarban. Siçi në 1638, pas shtypjes së kryengritjes kozake, u shkatërrua nga një fushatë polake. Termi: «Siçi» (ukrainisht Sich) është kampi qendror i kozakëve të Zaporizhisë në ishujt e Dnieprit, i fortifikuar me trungje dhe hendeqe; është qendra e shtabit, vendi i kuvendit (Rada) dhe i kreut të zgjedhur të ushtrisë (koshovoj), nuk është kryeqytet shteti. Në këtë datë «Hetmanati» ende nuk ekziston (1648); emri Zaporizhi do të thotë «përtej ujëvarave» dhe Siçet qëndrojnë në kufirin e stepës poshtë pragjeve (ujëvarave) të Dnieprit. Nuk ka lidhje etnike me kazakët e Kazakistanit: kozakët e Zaporizhisë janë një komunitet sllav lindor (ukrainas), ortodoks; e përbashkët është vetëm fjala me origjinë turke «kazak/kozak» (luftëtar i lirë).", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["Siçi i Mikitin Rogut përmendet për herë të parë", "61e22abc"], "d": ["Emri i Siçit të katërt, i ngritur në Mikitin Rog në vendin e Nikopolit të sotëm, përmendet për herë të parë në 1628; në 1648 u pushtua nga Bogdan Hmelnicki. Kjo është dëshmia e parë e njohur e vendit, jo themelimi i tij.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["U ndërtua Siçi i Çortomlikut", "4b6e8197"], "d": ["Kozakët e Zaporizhisë ndërtuan, në kepin ku Dniepri bashkohet me lumin Çortomlik, Siçin e Çortomlikut, i quajtur edhe 'Siçi i Vjetër'. Siçi u shkatërrua nga ushtria ruse më 25 maj 1709, sepse kishin mbështetur Mazepën.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Harkovi u themelua nga emigrantë kozakë", "288b303c"], "d": ["Në skajin verior të stepës së egër, në vendin ku bashkohen lumenjtë Lopan dhe Harkov, emigrantë kozakë të ardhur nga bregu i djathtë i Dnieprit themeluan një vendbanim. Harkovi pas pak u bë qendra e Ukrainës Slobodskaja të varur nga Moska.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["Kozakët e Zaporizhisë, me lejen e hanit të Krimesë, ndërtuan Siçin e Aleshkit", "ed26f29d"], "d": ["Kur ofensiva ruse i detyroi të boshatisnin Siçin në Kamenka, kozakët e Zaporizhisë, me lejen e hanit të Krimesë, u vendosën në tokat e hanatit, në Aleshki në bregun e majtë të lumit Konka. Pas Traktatit të Prutit u bashkuan me ta edhe kozakët e Gordijenkos. Hani nuk e lejoi Siçin të kishte mure dhe topa.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["Siçi i Aleshkit u plaçkit dhe u braktis", "52361709"], "d": ["Kozakët proruse të Samarës sulmuan dhe plaçkitën Siçin e Aleshkit dhe u vunë zjarrin kazermave. Siçi nuk u rindërtua; kozakët në 1730 u kthyen në Kamenka dhe në 1734, duke i bërë betim besnikërie Rusisë, ndërtuan Siçin e Ri.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["U ndërtua kështjella e Stavropolit në bregun e Vollgës", "eb087a50"], "d": ["Në Vollgën e Mesme, për kalmikët që pranuan krishterimin, u ndërtua kështjella e Stavropolit (Toljati i sotëm).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nadir Shahu merr Kandaharin dhe urdhëron shkatërrimin e qytetit të vjetër", "9cc23e6b"], "d": ["Sundimtari afshar Nadir Shah, pas një rrethimi të gjatë, mori Kandaharin që ishte në duart e afganëve gilzai. Qyteti u shkatërrua dhe populli u zhvendos në Nadirabad, të ndërtuar në juglindje të vendit të vjetër; Kandahari i vjetër nuk u bë më kurrë qytet.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["U ndërtua kështjella e Stavropolit në vijën Azov-Mozdok", "7fd9b9f1"], "d": ["Në vijën e fortifikimeve Azov-Mozdok, të ngritur pas Küçük Kajnarxhës për të kontrolluar stepën mes Kubanit dhe Terekut, u ndërtuan dhjetë kështjella; njëra prej tyre ishte Stavropoli. Kështjella më vonë u bë qendra e guvernatoratit të Kaukazit dhe gubernies së Stavropolit.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["U ngrit kantieri detar i Hersonit në grykën e Dnieprit", "115f2c34"], "d": ["Në grykën e Dnieprit, që pas Küçük Kajnarxhës kaloi te Rusia, pranë fortifikimit Aleksandr-shanc, të ndërtuar në 1737 dhe të rrëzuar pas pak, u ngrit një kantier detar dhe iu vu emri Herson. Qyteti në 1784 u bë qendër rrethi, në 1803 qendër gubernie.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Grekët e ardhur nga Krimea themeluan Mariupolin në bregun e Azovit", "4e3af209"], "d": ["Grekët e ardhur nga Krimea themeluan Mariupolin në vendin ku Kalmiusi derdhet në Detin Azov. Qyteti në 1784 u bë qendër rrethi e guvernatoratit të Jekaterinosllavit.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Jekaterinosllavi u zhvendos në vendin e sotëm në breg të Dnieprit", "ec361381"], "d": ["Jekaterinosllavi, që Potjomkini e kishte themeluar në 1778 në vendin ku bashkohen lumenjtë Kilçen dhe Samara, për shkak të pozitës së tij të pashëndetshme në 1783 u transferua në vendin e sotëm.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["Në gjirin e Ahtiarit u ngrit porti i flotës ruse Sevastopoli", "01058a25"], "d": ["Pas aneksimit të Krimesë nga Rusia në 1783, gjiri ku ndodhej fshati tatar i Krimesë Ahtiar (Akjar) u zgjodh për port ushtarak; porti u ngrit vitin pasardhës dhe mori emrin Sevastopol. Qyteti në 1804 u bë porti kryesor i flotës ruse të Detit të Zi.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["U ngrit fortifikimi i Nikollajevit në grykën e Bugut", "d57e52b9"], "d": ["Në vendin ku bashkohen lumenjtë Bugu Jugor dhe Inguli, me urdhrin e knjazit Potjomkin u ngrit një fortifikim. Në 1788 këtu u hap një kantier detar dhe vendbanimi u bë një nga qendrat e ndërtimit të anijeve për flotën e Detit të Zi.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Në bregun e Molloçnës u themelua vendbanimi kufitar që u bë bërthama e Melitopolit", "637d5817"], "d": ["Pas aneksimit të Krimesë, në bregun e lumit Molloçna u themelua një vendbanim kufitar. Vendbanimi në 1816 mori emrin Novooleksandrivka, në 1841 u bë qytet me emrin Melitopol.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["U themelua Novoçerkasku, qendra e re e Ushtrisë Kozake të Donit", "bf5709fd"], "d": ["Qendra administrative e Ushtrisë Kozake të Donit kaloi nga Çerkasku, deri atëherë qendër, te Novoçerkasku, i ndërtuar në vendin Birjuçij Kut mes lumenjve Aksaj dhe Tuzllov.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Vadi Halfa shënohet në udhëtimin e Burckhardt-it në Nubi", "6efc72ec"], "d": ["Udhëtari zviceran J. L. Burckhardt shkruan në ditarin e 6 marsit 1813 se kaloi nëpër Vadi Halfa dhe se atje bëhej njëfarë tregtie. Është dëshmia e parë e datuar që mund të gjendej.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["U ngrit skela e Berdjanskut në bregun e Azovit", "908ac3cf"], "d": ["Me nismën e knjazit Mihail Voroncov, Berdjansku u themelua në vendin ku lumi Berda derdhet në Detin Azov. Vendbanimi në 1835 u bë qytet, në 1842 qendër rrethi.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["Banorët e Malatjas qëndrojnë në vreshtat e Aspuzus — bërthama e Malatjas moderne", "d1dba159"], "d": ["Shtabi i përgjithshëm osman kundër ushtrisë egjiptiane të Ibrahim Pashës në verën e 1838-s u zhvendos nga Mezraa në Malatja. Banorët e Malatjas, që jetonin në shtëpitë verore në Aspuzu, pas largimit të ushtrisë nuk u kthyen në shtëpitë dimërore në qytetin e vjetër që kishte mbetur rrënojë; Aspuzu u bë bërthama e Malatjas moderne. Malatja e Vjetër (Battalgazi) vazhdoi të jetonte duke u zvogëluar.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Vani ngrihet në vendin e ri — qyteti i vjetër i shkatërruar braktiset", "6d278578"], "d": ["Vani u çlirua nga pushtimi më 2 prill 1918. Ata që u kthyen, në vend që të riparonin Vanin e vjetër në bregun e liqenit, të shkatërruar gjatë viteve të luftës, ngritën një qytet të ri rreth 7 km në brendësi nga bregu, në vendin e lagjeve të vjetra Norshen dhe Arak. Qyteti i vjetër u braktis.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Marashi kaloi te memlukët — nibi i Halepit Bilban et-Tabahi ua rimori armenëve", "03171265"], "d": ["Marashi, që që nga 1258 ishte në duart e Mbretërisë Armene të Kilikisë, në 1293, me traktatin e sulltan Halilit me armenët, kishte kaluar për pak kohë te memlukët dhe pas tërheqjes së tyre kishte rënë sërish në duart e armenëve. Në 697 (1298) nibi (guvernatori) memluk i Halepit, Bilban et-Tabahi, e rimori qytetin. Marashi pas kësaj mbeti tokë memluke deri në ngritjen e dulkadirlinjve.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Perandoria Bizantine u bë haraçpaguese e osmanëve", "615df998"], "d": ["Pas fitores së Çirmenit (1371), perandori bizantin Joani V pranoi në dimrin e 1372-s të ishte haraçpagues i Muratit I: do të paguante haraç vjetor dhe do t'i jepte ushtarë fushatave të sulltanit. Bizanti që nga kjo datë deri në 1403 mbeti shtet vasal i varur nga osmanët; bllokada e Bajazitit Jilldërëm e 1391-s e rriti haraçin. Traktati i Galipolit me Sulejman Çelebiun pas shpartallimit të Ankarasë (1403) e çliroi Bizantin nga haraçi; me traktatin e lidhur me Muratin II në 1424, haraçi filloi sërish.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Pas vdekjes së Barkukut, Bajaziti Jilldërëm ua bashkoi tokave osmane Besnin, Darenden dhe Divrigun", "8e57d7e6"], "d": ["Kur pas vdekjes së sulltanit memluk Barkuk (qershor 1399) punët administrative të Shtetit Memluk u prishën, Bajaziti Jilldërëm zbriti në pellgun e Eufratit dhe, bashkë me Malatjan, ua bashkoi tokave osmane Besnin (Behisni), Darenden dhe Divrigun. Sivasi para kësaj u ishte lënë osmanëve pas vdekjes së Kadi Burhanedinit në verën e 1398-s. Divrigu që nga 1391 ishte nën sundimin memluk dhe ishte një post i avancuar i lidhur me ejaletin e Halepit. Administrata osmane këtu nuk zgjati: për shkak të rrezikut të afrimit të Timurit, Divrigu në 1401 iu dha sërish memlukëve dhe hyrja përfundimtare e qytetit nën administratën osmane ndodhi pas Mexh Dabikut të 1516-s.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Gjatë fushatës së Timurit në Sivas dhe Malatja, Besni kaloi te memlukët", "4853da9a"], "d": ["Besni, që Bajaziti Jilldërëm e kishte marrë në 1398 bashkë me Sivasin, Darenden dhe Malatjan, në 1400, kur Timuri po merrte Sivasin dhe Malatjan, kaloi në duart e memlukëve. Më 27 shtator 1400, pas një rrethimi të ashpër, Timuri pushtoi edhe Besnin; kur u tërhoq nga ai rajon, Besni hyri sërish nën sundimin memluk dhe mbeti te memlukët (përveç një periudhe të ndërmjetme dulkadirli) derisa e mori Sulltan Selimi Javuz në gusht 1516.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Për shkak të rrezikut të Timurit, Divrigu iu dha sërish memlukëve", "97196b1f"], "d": ["Divrigu, që Bajaziti Jilldërëm ua kishte marrë memlukëve në 1398, kur Timuri po i afrohej Anadollit, u la sërish memlukëve në 1401. Prandaj, pasi Timuri shkatërroi Sivasin (1400), Divrigu shfaqet në hartë me ngjyrën memluke; në po ato muaj Bajaziti po merrte në lindje Erzinxhanin dhe Kemahun, pra toka memluke mbeti mes tokave osmane në perëndim (Sivas) dhe në verilindje (Kemah). Divrigu kaloi përfundimisht te osmanët vetëm pas Mexh Dabikut të 1516-s.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Sulltani memluk Shejh ua rimori dulkadirlinjve Antepin dhe Darenden", "f90c9508"], "d": ["Sulltani memluk Shejh, i shqetësuar nga miqësia e dulkadirlinjve me osmanët, doli në fushatë në 1414; rimori Antepin dhe Darenden, që më parë ua kishte dhënë dulkadirlinjve me vullnetin e vet.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Mehmed Beu i Dulkadirit rimori Darenden dhe ia bashkoi tokave të veta edhe Besnin", "df914dcb"], "d": ["Darenden, që memlukët e morën në 1414, Mehmed Beu i Dulkadirit e rimori në 1418 dhe ia bashkoi tokave të veta edhe Besnin.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Memlukët mundën dulkadirlinjtë në Antep; Besni u kthye nën administratën memluke (përafërsisht)", "72742430"], "d": ["Ushtria memluke mundi në 1436 dulkadirlinjtë në Antep dhe Mehmed Beu u tërhoq në Akdag. Viti i kthimit të Besnit te memlukët nuk është i shënuar te burimi; Besni iu bashkua Dulkadirit në 1418 dhe u kthye te memlukët para se Shehsuvar Beu ta merrte prej tyre në 1465. Atlasi ia kthen Besnin memlukëve bashkë me këtë disfatë në qendrën fqinje, Antep (përafërsi e deklaruar).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Shehsuvar Beu i Dulkadirit ua mori Besnin memlukëve (përafërsisht)", "843f0fc4"], "d": ["Shehsuvar Beu (1465-1472), i emëruar bej i Dulkadirit nga Sulltan Mehmeti Fatih, pushtoi Besnin, Gergerin, Birexhikun dhe Rumkalen, që ishin në duart e memlukëve; memlukët u mundën në Turnadag në vjeshtën e 1467-s dhe pranë Antepit në pranverën e 1468-s.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emir Jeshbeku mundi Shehsuvar Beun; Besni u kthye nën administratën memluke (përafërsisht)", "4d856aee"], "d": ["Në pranverën e 1471-s Emir Jeshbeku mundi Shehsuvar Beun në luginën e Savronit; memlukët rimorën Kadirlin dhe Kozanin. Shehsuvari u ekzekutua në Kajro në 1472 dhe memlukët e rikthyen Shahbudakun në krye të bejlikut. Me këtë kthim edhe Besni hyri nën administratën memluke (TDV besni: 'nga fundi i shekullit XV kaloi sërish në duart e memlukëve').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Forcat e Ferdinandit zunë Szolnokun dhe e fortifikuan", "6c8416e6"], "d": ["Ndërsa osmanët po përgatiteshin të ngrinin kështjellë në Szolnok mbi Tisë, forcat e Ferdinandit I ua kaluan: në mesin e shtatorit 1550 zunë Szolnokun dhe në mes të tetorit kështjella u bë e mbrojtshme. Kështu Szolnoku, që i përkiste vendit të Izabelës, kaloi në duart habsburge një vit para kalimit të Transilvanisë te Ferdinandi; osmanët e morën kështjellën në 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Transilvania kaloi nën administratën habsburge: kuvendi i Kolozsvárit njohu heqjen dorë të Izabelës", "8458a566"], "d": ["Pas marrëveshjes së Martinuzzit me Ferdinandin, mbretëresha Izabela, në emër të mbretit të vogël János Zsigmond, nënshkroi më 19 qershor 1551 në kështjellën e Szászsebesit aktin e heqjes dorë që iu imponua. Më 26 korrik kuvendi i Transilvanisë, i mbledhur në Kolozsvár, e njohu këtë heqje dorë dhe sundimin e mbretit Ferdinand; ushtria habsburge e gjeneralit Castaldo hyri në Alba Julia të Transilvanisë (Gyulafehérvár). Kështu Transilvania e varur nga osmanët kaloi në një administratë habsburge që do të zgjaste pesë vjet.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Administrata habsburge mori fund në Transilvani: Transilvania u bë sërish vojvodat i varur nga osmanët", "721a482a"], "d": ["Përmes priftit me origjinë kroate Martinuzzi (Fráter György), i emëruar kujdestar i János Zsigmond për shkak të moshës së tij të vogël, Habsburgët në 1551 u përpoqën të sundonin Transilvaninë; Alba Julia (Gyulafehérvár), Kaloshvari, Brassó dhe Segesvári mbetën pesë vjet nën administratën habsburge. Osmanët e penguan këtë gjendje dhe Transilvania u bë sërish një vojvodat haraçpagues i varur prej tyre. Më pas Transilvania, gjatë shekujve XVI dhe XVII, për rreth 150 vjet ruajti statusin e mbështetur në autonomi të gjerë në punët e brendshme dhe varësi nga Stambolli në ato të jashtme.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Váradi, Huszti dhe Tokaji kaluan në anën e Szapolyait", "587c782d"], "d": ["Pas kthimit të Izabelës dhe János Zsigmond në Transilvani në 1556, partizanët e Szapolyait rrethuan Nagyváradin në 1556. Në 1557 aristokratët e Tisës së Sipërme pushtuan kështjellat më të rëndësishme mbretërore — Váradin, Husztin dhe Tokajin; Ferdinandit i mbetën vetëm Gyula dhe Világosi. Váradi pas kësaj u bë kështjellë e principatës së Transilvanisë dhe mbeti e tillë derisa e morën osmanët në 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi mori Szatmárin — skaji verior i Transilvanisë kaloi te Habsburgët", "2256bb27"], "d": ["Szatmárin, që në 1561 kishte kaluar te Habsburgët me ndërrimin e anës nga Balassa Menyhért, István Báthory e kishte rimarrë me një sulm të befasishëm në vjeshtën e 1564-s dhe ia kishte bashkuar Transilvanisë. Komandanti habsburg Lazarus von Schwendi kaloi në kundërsulm në shkurt 1565: Tokaji ra më 9 shkurt, Szerencs katër ditë më vonë dhe Szatmári kaloi pothuajse pa rezistencë në duart e forcave perandorake.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Forcat e Bocskait morën Szatmárin", "e93b098b"], "d": ["Ndërsa kryengritja e Bocskait po përhapej në Hungarinë verilindore, Gyulaffy pushtoi më 21 janar 1605 Szatmárin që e kishte rrethuar. Paqja e Vjenës e 23 qershorit 1606 ia la Bocskait përjetë komitatin e Szatmárit; meqë nuk kishte trashëgimtar mashkull, me vdekjen e Bocskait më 29 dhjetor 1606 komitati iu kthye mbretërisë.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Vdekja e Bocskai Istvánit — komitati i Szatmárit iu kthye mbretërisë", "3721bb9b"], "d": ["Princi i Transilvanisë Bocskai István vdiq më 29 dhjetor 1606 në Kassa. Paqja e Vjenës (23 qershor 1606) ia kishte lënë përjetë komitatet, përfshirë Szatmárin, me kusht që në rast se nuk kishte trashëgimtar mashkull t'i ktheheshin mbretërisë; në bazë të kësaj dispozite komitati i Szatmárit iu kthye mbretërisë hungareze habsburge. Transilvania nisi të kërkonte një princ të ri.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor mori nën kontroll komitatin e Szatmárit", "80263da1"], "d": ["Me fushatën e Bethlen Gáborit në Hungari në vjeshtën e 1619-s, komitati i Szatmárit hyri nën kontrollin e princit të Transilvanisë; në nëntor 1619 ai i drejtohej komitatit me letër. Traktati paraprak i 23 janarit 1620 dhe paqja e Nikolsburgut ia lanë Bethlenit përjetë shtatë komitate, përfshirë Szatmárin. Pas vdekjes së Bethlenit (15 nëntor 1629), kthimi i komitateve te mbretëria u përfundua më 30 mars 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["U përfundua kthimi i shtatë komitateve të Bethlen Gáborit te mbretëria", "31b5968f"], "d": ["Paqja e Nikolsburgut ia kishte lënë përjetë Bethlen Gáborit shtatë komitate të Hungarisë së Sipërme, përfshirë Szatmárin. Pas vdekjes së Bethlenit më 15 nëntor 1629, kthimi i komitateve te mbretëria filloi me udhëzimin e 30 nëntorit 1629 dhe u përfundua më 30 mars 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György I Rákóczi mori në dorëzim Szatmárin", "f398635b"], "d": ["Në fushatën e 1644-s të princit të Transilvanisë György I Rákóczi, garnizoni gjerman i Szatmárit kaloi në shërbim të Rákóczit dhe kështjella kaloi në duart e Transilvanisë. Paqja e Linzit e 16 dhjetorit 1645 ua la kështjellën trashëgimtarëve të Rákóczit, për sa kohë që në fronin e Transilvanisë të ishte një Rákóczi.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Humbja e Nitrës — De Souches rimori kështjellën", "c71bf012"], "d": ["Pas pushtimit të Ujvarit në 1663, Nitrën, që ishte dorëzuar pas një rezistence të shkurtër, komandanti perandorak De Souches e rrethoi më 15 prill 1664; kështjella u dorëzua më 3 maj 1664. Meqë Traktati i Vasvarit i la vendet e marra siç ishin, Ujvari mbeti te osmanët, kurse Nitra mbeti në duart habsburge.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Humbja e Lévas", "f311920e"], "d": ["Pas Nitrës, De Souches e rrethoi Lévan më 9 qershor 1664; më 13 qershor u nënshkrua kapitullimi dhe më 14 qershor kështjella ishte në duart e forcave perandorake. Beteja e Lévas (Garamszentbenedek) e 19 korrikut 1664 nuk e ndryshoi zotërimin; përfundoi me mbajtjen e Lévas dhe Nitrës nga Habsburgët.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroshenko ia dorëzoi Çigirinin Samojloviçit", "3b538237"], "d": ["Hetmani i Bregut të Djathtë nën protektoratin osman, Petro Doroshenko, ia dorëzoi më 19 shtator 1676 kryeqytetin Çigirin hetmanit të Bregut të Majtë Samojloviç dhe forcave ruse. Osmanët e shkarkuan Doroshenkon dhe vunë në vend të tij Juri Hmelnickin; rrethimi i 1677-s për të nxjerrë garnizonin rus nga Çigirini dështoi dhe kështjella u mor vetëm më 21 gusht 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Dorëzimi i kështjellave të Banatit të Transilvanisë (Temeshvar, Lippa, Lugoj, Karánsebes) mbretit të Hungarisë Ferdinand", "0e354976"], "d": ["Në 1551 ushtria habsburge nën komandën e gjeneralit Castaldo hyri në Transilvani; mbretëresha Izabela dhe i biri u detyruan të hiqnin dorë nga të drejtat mbi fronin e Hungarisë. Martinuzzi, me miratimin e Castaldos, në mes të korrikut 1551 dërgoi Báthory Endren për të marrë në dorëzim në emër të Ferdinandit kështjellat e Temeshvarit, Lippës, Solymosit, Karánsebesit, Lugojit, Becses, Becskerekut dhe Çanadit. Kështu kështjellat jugore të Transilvanisë nën protektoratin osman kaluan në duart habsburge; fushatat e Kanuniut të 1551-1552 janë përgjigjja ndaj kësaj.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Emërimi i Petrovics Péterit sanxhakbej i Lugojit dhe Karánsebesit", "bcbe73e4"], "d": ["Me lutjen këmbëngulëse të Izabelës dhe Petrovics-it, Kanuniu vendosi ta kthente në Transilvani János Zsigmondin e vogël. Me letrën që shkroi nga Halepi më 7 prill 1554, urdhëroi Transilvaninë ta kthente fëmijën në vendin e vet; edhe vojvodëve të Vllahisë dhe Moldavisë u dha urdhër ta ndihmonin në këtë punë Petrovics-in, të cilin në të njëjtën kohë e emëroi sanxhakbej të Lugojit dhe Karánsebesit. Kështu Lugoji, i pushtuar në 1552, iu dha Petrovics-it si sanxhak osman.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Heqja e rrethimit të Lippës — sulmi i banit të Lugojit mbi Temeshvar", "be03430e"], "d": ["Në pranverën e 1596-s pashai i Temeshvarit rrethoi Lippën. Natën nga 10 për në 11 maj, me urdhrin e banit transilvan të Lugojit Palatics György, ushtarët e Buday Györgyt sulmuan dhe i vunë zjarrin varoshit të Temeshvarit; edhe fakti që Borbély György në kështjellë urdhëroi të qëlloheshin të gjitha topat e bindi pashain se kishte ardhur ndihma. Pashai u tërhoq nga Lippa më 11 maj dhe nxitoi të mbronte qendrën e vet. Lugoji në këtë kohë ishte në duart e Principatës së Transilvanisë.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Pushtimi i Orshovës nga forcat austriake nën komandën e Veteranit", "1b4a4f6c"], "d": ["Në fushatën e 1688-s, gjenerali Veterani, pasi mori Karánsebesin, marshoi drejt Orshovës dhe e pushtoi edhe atë. Dita e pushtimit mungon te burimi; është përdorur 1 janari 1688 si bazë vjetore.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Rimarrja e Orshovës nga forcat e Thököly-t dhe osmane", "c5645da9"], "d": ["Drejt Orshovës, që Veterani e pushtoi në 1688, pas marrjes së Vetislanit marshuan Thököly dhe pashallarët osmanë. Pas përplasjeve të parëndësishme, Thököly hyri në Orshovë më 15 korrik 1689. Heissler, që erdhi me lajmin e rrezikut, duke parë se forca përballë ishte e pajisur mirë me municion dhe anije, u tërhoq për të mbrojtur Transilvaninë. Edhe sulmi i Herbeville-it para qytetit në gusht nuk e rimori Orshovën.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Sanxhaku i Lugojit hyri nën pushtimin habsburg (1691-1695)", "c8bcd6bd"], "d": ["Sanxhaku i Lugojit mbeti nën pushtimin habsburg (gjerman) në 1691-1695; Mustafai II e ripushtoi më 22 shtator 1695. Në shënimin e vjetër, periudha 1689-1695 ishte boshllëk i deklaruar; segmenti 1691-1695 tani ngjyroset si habsburg, kurse 1689-1691 mbetet boshllëk. Data është marrë vetëm si vit.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Kështjella e Lugojit hyri nën administratën habsburge", "6a9d401f"], "d": ["Kështjella e sanxhakut Lugoj, e varur nga ejaleti i Temeshvarit, që nga 1695 ishte në duart osmane; me dorëzimin e qendrës së ejaletit në fund të rrethimit të 1716-s, iu la Monarkisë Habsburge. Shënimi i vjetër e vendoste kalimin më 1 janar 1716, bazë vjetore.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Marrja e Orshovës nga ushtria habsburge (fushata e 1717-s)", "7a4faffe"], "d": ["Në fushatën e 1717-s, gjenerali Splényi arriti para Orshovës më 27 gusht dhe e mori lehtë qytetin; kështu Orshova, që Mercy nuk mundi ta merrte në 1716, kaloi në duart habsburge. Meqë qelizat përreth në bregun e Danubit (përfshirë segmentin Đerdap në anën serbe) lidhen me Orshovën, pikën më të afërt të vendbanimit, ngjyrosen me zotëruesin e saj. Data është marrë vetëm si vit; dita e saktë nuk është e konfirmuar.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Kalimi i palankës së Orshovës te osmanët — rojet u tërhoqën në Adakale", "de759b16"], "d": ["Në fillim të fushatës së 1738-s, komandanti i Vidinit Haxhi Mehmed Pasha sulmoi fortifikimin Erzsébet përgjatë Danubit. Pasditen e 8 majit një njësi spahinjsh prej 4-5 mijë vetash marshoi nga bregu i majtë i Danubit drejt Orshovës dhe sulmoi palankën e Orshovës; garnizoni austriak, që pati rreth njëqind humbje, u tërhoq në Orshovën e Re, pra në kështjellën ishullore Adakale. Pas përplasjeve të Mehadisë në korrik, edhe Adakalja kaloi në duart osmane në gusht 1738; Traktati i Beogradit i 1739-s e njohu këtë gjendje.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murati II mori Alaxhahisarin, Nishi dhe Shehirkoy u kthyen te osmanët", "54af926a"], "d": ["Pas vdekjes pa trashëgimtar të despotit serb Stefan Llazareviq (1427), Murati II, duke u mbështetur në martesën e Bajazitit Jilldërëm me një princeshë serbe, pretendoi se ishte trashëgimtari legjitim i Serbisë, veproi dhe mori Alaxhahisarin (Kruševac) (1428). Po atë vit, pas vdekjes së Llazareviqit, osmanët rimorën edhe kështjellën e Shehirkoyit (Pirot) — qyteti në 1412 ishte marrë nga Stefani dhe ishte mbrojtur kundër Musa Çelebiut. Sipas zërit nis të TDV-së, osmanët rimorën edhe Nishin po atë vit (831/1428). Kështu vija që lidhte luginat e Moravës së Madhe dhe Nishavës hyri nën kontrollin osman.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Ushtria e kryqtarëve pushtoi Shehirkoyin — krahu i Nishavës i 'Fushatës së Gjatë'", "fdf6140c"], "d": ["Ushtria e kryqtarëve nën udhëheqjen e mbretit Vladisllav dhe despotit serb Gjuragj Brankoviq pushtoi Shehirkoyin në 1443. Në vazhdim të së njëjtës fushatë, forcat osmane do të shpartalloheshin në nëntor në grykën e Izladit. Shehirkoy, pas Traktatit të Szegedit (1444), iu dha sërish serbëve nga Murati II, por në 1456, pas vdekjes së Gjuragj Brankoviqit, kaloi te osmanët.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["U sigurua sundimi përfundimtar osman në krahinën e Alaxhahisarit", "9715382a"], "d": ["Alaxhahisari, që me traktatin e lidhur me delegatët hungarezë në 1444 iu la Brankoviqit, në vitet pas fitores së Varnës hyri sërish nën sundimin turk. Ky pushtim i dytë i qytetit dokumentohet jo me një shënim lufte, por me një shënim financiar: regjistrimet e timareve për disa fshatra të varura nga Alaxhahisari datohen në fund të 1453-s/fillim të 1454-s; por kjo është vetëm dëshmi për fshatrat — në 1454 forcat osmane u shpartalluan pranë Alaxhahisarit dhe në 1455 Alaxhahisari iu la si kufi Brankoviqit. Sipas TDV-së, sundimi përfundimtar osman në krahinë u sigurua në 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Themelimi i Despotatit të Moresë — Manueli Kantakuzen në Mistra", "87660b82"], "d": ["Perandori bizantin Joani Kantakuzen i dha të birit Manuel një rajon të veçantë qeverisjeje në More; kështu lindi Despotati i Moresë me qendër Mistrën. Manueli qeverisi deri në 1380; në këtë periudhë kultura dhe arti bizantin u zhvilluan veçanërisht në Mistra. Despotati zgjati deri në pushtimin e Fatihut në 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Despoti Konstandin ua mori frankëve Patrasin", "cb0dd18c"], "d": ["Despoti i Moresë Konstandini (në 1449 perandori i fundit bizantin) ua rimori latinëve Patrasin; kështu edhe ky port i rëndësishëm në veriperëndim të gadishullit iu bashkua despotatit. Patrasi hyri nën sundimin osman në fushatën e Fatihut në More në 1458.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčiq Kosaça 'Duka i Shën Savës' — lindja e Hercegovinës", "cc67061f"], "d": ["Stjepan Vukčiq Kosaça, që bashkoi Humin dhe Trebinjen në një bejlik të vetëm, u ngrit kundër mbretit të Bosnjës dhe e shpalli veten 'Herceg (dukë) i Shën Savës'; titullin ia dha në 1448 perandori Fridriku III. Emri Hercegovina ('vendi i hercegut') vjen nga ky titull. Hercegovina nga 1466 kaloi pjesë-pjesë te osmanët, në 1470 u bë sanxhak; tokat e mbetura iu bashkuan në fillim të 1482-s.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Paqja e Krakovit — shteti i Urdhrit Teuton u shndërrua në Dukatin e Prusisë", "78666ddd"], "d": ["Mjeshtri i madh i kalorësve teutonë, Albrehti i Brandenburgut, meqë nuk gjeti ndihmë kundër Polonisë, nënshkroi Paqen e Krakovit. Shteti i urdhrit (Ordensstaat), nën suzerenitetin polak, u bë një dukat trashëgimor dhe laik që kaloi te dinastia e Brandenburgut. Qendra ishte Königsbergu; Albrehti themeloi këtu Universitetin Albertus në 1544. Në 1701 dukati u shndërrua në Mbretërinë e Prusisë.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Shpallja e Republikës së Austrisë — fundi i monarkisë habsburge", "c84f316c"], "d": ["Të nesërmen pasi perandori Karl I u tërhoq nga punët e shtetit më 11 nëntor, Asambleja Kombëtare e Përkohshme miratoi ligjin për formën e shtetit dhe qeverisjes dhe u shpall republika. Vendin e Austrisë habsburge e zuri Republika e Parë me qendër Vjenën. Me këtë shpallje, Vjena, Linci, Salcburgu, Insbruku, Klagenfurti, Bregenci dhe qytetet e tjera gjermano-austriake u bënë toka të Republikës së Austrisë (Deutschösterreich).", "2dcc1399"]},
"OLAYLAR_T5_1000A:1008-01-01:0":{"b": ["Batumi nën sundimin e Mbretërisë/Mbretërive të Gjeorgjisë — dëshmia e datuar në burim", "62cd2833"], "d": ["Burimi e tregon qytetin e Batumit në këtë datë nën administratën e Mbretërisë/Mbretërive të Gjeorgjisë; zotërimi më i hershëm nuk është i datuar në burim (atlasi e lë bosh periudhën para kësaj date).", "e03655c9"]},
"OLAYLAR_T5_1000A:1024-01-01:0":{"b": ["Mervanidi Nasruddevle e bashkoi Amidin me emiratin e vet", "9fbc8c85"], "d": ["Emiri mervanid Nasruddevle Ahmed e bashkoi Amidin (Dijarbekirin) me tokat e emiratit; vitin pasardhës mori edhe Urfën.", "d585a28b"]},
"OLAYLAR_T5_1000A:1054-01-01:0":{"b": ["Maraga hyri nën sundimin selxhuk", "c011cac9"], "d": ["Maraga, në duart e Revvadidëve, hyri nën sundimin selxhuk me fushatën e Tugrul Beut në Azerbajxhan.", "2ff74d2d"]},
"OLAYLAR_T5_1000A:1055-12-18:0":{"b": ["Tugrul Beu hyri në Bagdad", "38af55c2"], "d": ["Tugrul Beu, që erdhi në Bagdad me ftesën e kalifit Kaim-Bi-emrillah, i dha fund sundimit buvejhid.", "f7f905d1"]},
"OLAYLAR_T5_1000A:1056-01-01:0":{"b": ["Mosuli kaloi në duart e selxhukëve", "20b8da93"], "d": ["Mosuli, bashkë me Irakun, u kaloi selxhukëve; megjithë pushtimin e shkurtër nga Besasiri, mbeti katër vjet në duart selxhuke.", "a55cff1d"]},
"OLAYLAR_T5_1000A:1061-01-01:0":{"b": ["Mosuli sërish te ukajlidët", "8b7c0603"], "d": ["Mosuli hyri sërish nën sundimin ukajlid në 1061; edhe pas pushtimit selxhuk të 1084, Melikshahu ia ktheu qytetin emirit ukajlid.", "71824a2b"]},
"OLAYLAR_T5_1000A:1064-01-01:0":{"b": ["Alparslani i dha fund shahllëkut të Nahçivanit", "5620360e"], "d": ["Alparslani, që mundi Revvadidët, e zhduku shahllëkun e Nahçivanit të themeluar nga dulefidët.", "f9fd7d73"]},
"OLAYLAR_T5_1000A:1071-01-01:0":{"b": ["Emir Salltuku pushtoi Erzurumin", "f52c09dd"], "d": ["Pas Malazgirtit, Alparslani ia dha si ikta Emir Salltukut rrethinat e Erzurumit; Salltuku po atë vit mori qytetin dhe u themelua Bejliku Salltukid (sipas Yinanç-it në 1080).", "505fcc25"]},
"OLAYLAR_T5_1000A:1071-01-01:1":{"b": ["Danishmend Gaziu pushtoi Sivasin", "348d7ad3"], "d": ["Danishmend Gaziu, që mori Sivasin, i dhënë si ikta pas Malazgirtit, themeloi aty bërthamën e dinastisë (data e pushtimit është e diskutueshme; ka edhe një version për 1080).", "b9b5dd65"]},
"OLAYLAR_T5_1000A:1074-01-01:0":{"b": ["Filareti pushtoi Malatjen", "9c80e3bd"], "d": ["Filareti, që themeloi një principatë armene në Kiliki, duke u paraqitur si përfaqësues i Bizantit mori Malatjen dhe e qeverisi nëpërmjet guvernatorëve (Gabrieli etj.).", "958ede64"]},
"OLAYLAR_T5_1000A:1074-01-01:1":{"b": ["Emir Danishmendi pushtoi Tokatin", "c9321fb6"], "d": ["Pas fitores së Malazgirtit, Emir Danishmendi ia mori Tokatin Bizantit.", "dcc7f8e2"]},
"OLAYLAR_T5_1000A:1085-01-01:0":{"b": ["Selxhukët morën Hasankejfin nga mervanidët", "4fa9d559"], "d": ["Në kohën e Melikshahut selxhukët i dhanë fund sundimit mervanid dhe morën edhe Hasankejfin.", "b9794646"]},
"OLAYLAR_T5_1000A:1085-05-31:0":{"b": ["I biri i Fahruddevles mori Amidin, sundimi mervanid mori fund", "ecaf6b03"], "d": ["Zaimurruesa, i biri i Fahruddevle Ibn Xhehirit të ngarkuar nga Melikshahu, ua mori Amidin mervanidëve.", "8745ce9d"]},
"OLAYLAR_T5_1000A:1093-01-01:0":{"b": ["Tutushi pushtoi Dijarbekirin", "469b8ebc"], "d": ["Pas vdekjes së Melikshahut, Tutushi, që pretendonte sulltanatin, mori rajonin e Dijarbekirit dhe zuri rob emirin e fundit mervanid, Mansurin.", "52daa285"]},
"OLAYLAR_T5_1000A:1095-01-01:0":{"b": ["Beu turkmen Sadr filloi të sundonte në Amid", "3d67b786"], "d": ["Pas vdekjes së Tutushit, beu turkmen Sadr u bë zot i Amidit; pasardhësi i tij, Inali, themeloi dinastinë Inalogullarë.", "5fdca35c"]},
"OLAYLAR_T5_1000A:1096-01-01:0":{"b": ["Kurboga pushtoi Mosulin", "462a238f"], "d": ["Emiri selxhuk Kurboga ua mori Mosulin ukajlidëve. (Dhulkade 489 / nëntor 1096; atlasi, duke ndjekur regjistrin, e shkruan me saktësi viti.)", "14d9ca6d"]},
"OLAYLAR_T5_1000A:1100-01-01:0":{"b": ["Niksari nën sundimin e Danishmendidëve — dëshmia e datuar në burim", "81181870"], "d": ["Burimi e tregon qytetin e Niksarit në këtë datë nën administratën e Danishmendidëve; zotërimi më i hershëm nuk është i datuar në burim (atlasi e lë bosh periudhën para kësaj date).", "c1463e88"]},
"OLAYLAR_T5_1000A:1102-09-18:0":{"b": ["Danishmendidi Gumyshtegin Gaziu mori Malatjen", "87f1166c"], "d": ["Gumyshtegin Gaziu, në fund të rrethimit, pushtoi Malatjen.", "2d0e9668"]},
"OLAYLAR_T5_1000A:1106-09-02:0":{"b": ["Kilixharslani I mori Malatjen në dorëzim", "eca366d5"], "d": ["Pas vdekjes së Gumyshteginit, Kilixharslani I, me një rrethim mbi dymujor, e bashkoi Malatjen me tokat selxhuke.", "69bdbc2c"]},
"OLAYLAR_T5_1000A:1108-03-04:0":{"b": ["Mezjedidi Sadaka vdiq në Numanije, Hilla te selxhukët", "e5ecea7c"], "d": ["Muhamed Tapari mundi Sadakën; i biri, Dubejsi, ra rob dhe nuk iu lejua të kthehej në Hillë.", "be1e2910"]},
"OLAYLAR_T5_1000A:1111-01-01:0":{"b": ["Ilarslani ia rimori Elbistanin Tankredit", "923962c2"], "d": ["Elbistanin, që e kishte marrë princi i Antiokisë Tankredi, e rimori Ilarslani, atabegu i melikut të Malatjes Tugrul Arslanit.", "ce0754bd"]},
"OLAYLAR_T5_1000A:1112-01-01:0":{"b": ["Artukidi Belek u bë zot i Harputit", "83425a6e"], "d": ["Belek b. Behram, nipi i Artuk Beut, u bë zot i Harputit dhe themeloi bejlikun e vet me qendër Palu.", "ff838897"]},
"OLAYLAR_T5_1000A:1116-01-01:0":{"b": ["Nigdeja nën sundimin e Shtetit Selxhuk të Anadollit (Turqisë) — dëshmia e datuar në burim", "dfb24c4b"], "d": ["Burimi e tregon qytetin e Nigdes në këtë datë nën administratën e Shtetit Selxhuk të Anadollit (Turqisë); zotërimi më i hershëm nuk është i datuar në burim (atlasi e lë bosh periudhën para kësaj date).", "477146f3"]},
"OLAYLAR_T5_1000A:1117-01-01:0":{"b": ["Dubejsi u kthye në Hillë", "9bc0e03a"], "d": ["Pas vdekjes së Muhamed Taparit, Dubejsi mundi të shkonte në Hillë në kohën e sulltanit selxhuk të Irakut, Mahmudit.", "d9aec87c"]},
"OLAYLAR_T5_1000A:1118-05-06:0":{"b": ["Mahmudi u shpall në Bagdad sulltan selxhuk i Irakut — u themelua Shteti Selxhuk i Irakut", "18babf94"], "d": ["Pas vdekjes së Muhamed Taparit, i biri, Mahmudi, u shpall sulltan nga kalifi; u themelua Shteti Selxhuk i Irakut. Bagdadi, Mosuli dhe Tikriti mbetën të lidhur me sulltanatin selxhuk të Irakut, dhe edhe Azerbajxhani (Maraga, Nahçivani) i ra pjesës selxhuke të Irakut. Tikriti në këtë vit përmendet në burim si ikta e shahnesë së Bagdadit.", "cf36af86"]},
"OLAYLAR_T5_1000A:1119-01-01:0":{"b": ["Joan II Komneni rimori Denizlinë", "cb523c0f"], "d": ["Perandori bizantin Joan II Komneni e detyroi komandantin selxhuk në Laodice, Alp Karanë, të tërhiqej; tokat e Denizlisë i kaluan sërish Bizantit (zëri bizantin thotë 1120).", "8bdb49b8"]},
"OLAYLAR_T5_1000A:1120-01-01:0":{"b": ["Aksungur el-Ahmedili u dërgua në Maraga", "7a3d6deb"], "d": ["Sulltan Mahmudi dërgoi Aksungur el-Ahmedilin në Maraga; atabegati Ahmedili u vendos në qytet.", "3616b62c"]},
"OLAYLAR_T5_1000A:1124-12-10:0":{"b": ["Emir Gaziu danishmendid mori Malatjen në dorëzim; edhe Elbistani u kaloi Danishmendidëve", "97f3f958"], "d": ["Pas vdekjes së Belekut, Emir Gaziu me një rrethim të gjatë ia mori Malatjen melikut selxhuk Tugrul Arslanit; me pushtimin e rrethinës së Malatjes, edhe Elbistani hyri nën administratën danishmendide.", "ae95651d"]},
"OLAYLAR_T5_1000A:1127-01-01:0":{"b": ["Emir Gaziu ua mori Ankaranë selxhukëve", "25b745cd"], "d": ["Emir Gaziu danishmendid mundi melikun Arab, birin e Kilixharslanit I, dhe ia mori Ankaranë.", "008f5e3f"]},
"OLAYLAR_T5_1000A:1127-01-01:1":{"b": ["Imaduddin Zengiu atabeg i Mosulit (Zengidët)", "ba79276b"], "d": ["Sulltani selxhuk i Irakut Mahmudi ia dha Mosulin si ikta Imaduddin Zengiut; u themelua Atabegati i Mosulit.", "a1929772"]},
"OLAYLAR_T5_1000A:1134-01-01:0":{"b": ["Kajseri nën sundimin e Danishmendidëve — dëshmia e datuar në burim", "3b9b8604"], "d": ["Burimi e tregon qytetin e Kajserit në këtë datë nën administratën e Danishmendidëve; zotërimi më i hershëm nuk është i datuar në burim (atlasi e lë bosh periudhën para kësaj date).", "e82b707e"]},
"OLAYLAR_T5_1000A:1142-01-01:0":{"b": ["Kemahu nën sundimin e Menguxhukidëve (Mengüçekoğulları) — dëshmia e datuar në burim", "d86927c6"], "d": ["Burimi e tregon qytetin e Kemahut në këtë datë nën administratën e Menguxhukidëve (Mengüçekoğulları); zotërimi më i hershëm nuk është i datuar në burim (atlasi e lë bosh periudhën para kësaj date).", "fcb6186c"]},
"OLAYLAR_T5_1000A:1144-01-01:0":{"b": ["Sulltan Mesudi mori Elbistanin", "825e2c56"], "d": ["Mesudi I pushtoi Elbistanin dhe Xhejhanin, në duart e Ajnuddevles, dhe emëroi meli të birin, Kilixharslanin.", "d69cdacb"]},
"OLAYLAR_T5_1000A:1148-01-01:0":{"b": ["Nahçivani u bashkua me Ildenizidët", "774400cc"], "d": ["Me shpërbërjen e selxhukëve, Nahçivani iu bashkua Shtetit të Ildenizidëve dhe mbeti qendra e tyre deri në 1174 (viti i bashkimit nuk jepet; fillimi i dinastisë).", "bf42d3bd"]},
"OLAYLAR_T5_1000A:1149-01-01:0":{"b": ["Tikriti u kaloi Begteginidëve (EI2)", "a2caf5af"], "d": ["Sipas asaj që TDV përcjell nga EI2, Tikriti midis viteve 1149-1190 ishte nën sundimin e Begteginidëve.", "d10d23e8"]},
"OLAYLAR_T5_1000A:1150-04-30:0":{"b": ["Sulltan Mesudi ia dha Hillën Salarkerdit", "4bdbd034"], "d": ["Pas vdekjes së mezjedidit Ali, Sulltan Mesudi ia dha Hillën komandantit të tij Salarkerd.", "059e9aeb"]},
"OLAYLAR_T5_1000A:1152-04-08:0":{"b": ["Sulltan Mesudi vdiq; kalifi Muktefi u bë zot i vetëm në Irak, mori Hillën, Kufën dhe Vasitin", "21192405"], "d": ["Me vdekjen e Sulltan Mesudit, kalifi Muktefi-Li-emrillah vendosi në Bagdad dhe Irak një sundim të pavarur nga ndikimi selxhuk; veziri i kalifit pushtoi Hillën, u pushtuan edhe Kufa dhe Vasiti.", "cd348b82"]},
"OLAYLAR_T5_1000A:1156-01-01:0":{"b": ["Jagëbasani pushtoi Elbistanin", "824708d3"], "d": ["Pas vdekjes së Mesudit, meliku danishmendid i Sivasit, Jagëbasani, mori Elbistanin; me marrëveshje administrata iu la atij.", "d413e508"]},
"OLAYLAR_T5_1000A:1156-01-01:1":{"b": ["Komandantët selxhukë morën Hillën, Mezjedidët vartës të zëvendësit", "43afd955"], "d": ["Hilla u mor nga komandantët e sulltan Muhamed b. Mahmudit; Mezjedidët sunduan si vartës të zëvendësit të sulltanit.", "c6c81147"]},
"OLAYLAR_T5_1000A:1160-01-01:0":{"b": ["Baku nën sundimin e Shirvanshahëve — dëshmia e datuar në burim", "1f2863e4"], "d": ["Burimi e tregon qytetin e Bakusë në këtë datë nën administratën e Shirvanshahëve; zotërimi më i hershëm nuk është i datuar në burim (atlasi e lë bosh periudhën para kësaj date).", "506dae86"]},
"OLAYLAR_T5_1000A:1163-01-01:0":{"b": ["Kalifi Mustenxhid mori Hillën, Mezjedidët morën fund", "4348923c"], "d": ["Njësitë e kalifit Mustenxhid dhe të Beni Muntefikut pushtuan Hillën, Mezjedidët u shpërndanë.", "da071466"]},
"OLAYLAR_T5_1000A:1165-01-01:0":{"b": ["Kilixharslani II mori Elbistanin dhe Darenden", "7c109007"], "d": ["Duke përfituar nga grindja midis Danishmendidëve, Kilixharslani II pushtoi Elbistanin, Darenden dhe rrethinën e Gedykut.", "d258bac6"]},
"OLAYLAR_T5_1000A:1172-01-01:0":{"b": ["Rubenidi Mleh ia mori Tarsusin Bizantit", "2f98fd11"], "d": ["Rubenidi Mleh, me ndihmën e Nureddin Zengiut, ua rimori bizantinëve Adanën, Misisin dhe Tarsusin.", "e1cfa006"]},
"OLAYLAR_T5_1000A:1174-01-01:0":{"b": ["Ildenizidi Pehlivan mori Tabrizin", "f0831f17"], "d": ["Ildenizidi Pehlivan ua mori Tabrizin Ahmedilidëve me rrugë paqësore dhe ia dha vëllait të tij Kizilarslanit.", "81ee8ab8"]},
"OLAYLAR_T5_1000A:1175-01-01:0":{"b": ["Kilixharslani II ua mori Sivasin dhe Niksarin Danishmendidëve", "584575bb"], "d": ["Pas vdekjes së Nureddin Zengiut, Kilixharslani II pushtoi në verën e 1175 Sivasin, Niksarin, Tokatin dhe tokat e tjera danishmendide; dega e Sivasit mori fund.", "c8092aea"]},
"OLAYLAR_T5_1000A:1178-10-25:0":{"b": ["Kilixharslani II mori Malatjen, dega danishmendide mori fund", "3bdbb060"], "d": ["Pas një rrethimi katërmujor, Malatja u kaloi selxhukëve dhe dega danishmendide e Malatjes mori fund.", "b92d6ebb"]},
"OLAYLAR_T5_1000A:1183-04-29:0":{"b": ["Selahudini mori Amidin dhe ia dha artukidit Nureddin Muhamed", "8c3cc7bb"], "d": ["Selahudin Ajubi rrethoi dhe mori Amidin dhe ia dha emirit artukid të Hisn Kejfës, Nureddin Muhamedit; Inalogullarët morën fund.", "b16cdda4"]},
"OLAYLAR_T5_1000A:1184-01-01:0":{"b": ["Rubeni III ua rimori Adanën kryqtarëve", "e9876f85"], "d": ["Misisin, Adanën dhe Tel Hamdunin, që pas Mlehut për një kohë u kishin kaluar kryqtarëve, i rimori në 1184 rubenidi Ruben III.", "177b5432"]},
"OLAYLAR_T5_1000A:1190-01-01:0":{"b": ["Tikriti u kaloi Abasidëve", "e8f5aeac"], "d": ["Pas sundimit begteginid, qyteti kaloi nën administratën e kalifatit abasid.", "f91cfb0d"]},
"OLAYLAR_T5_1000A:1194-01-01:0":{"b": ["Rukneddin Sulejman Shahu II rimori Samsunin", "0971ebcd"], "d": ["Samsunin dhe tokat e Detit të Zi lindor, që gjatë grindjeve midis vëllezërve u kishin kaluar Komnenëve, i rimori Sulejman Shahu.", "940e4b5b"]},
"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["Adana dhe Tarsusi: principata rubenide u shndërrua në Mbretërinë Armene të Kilikisë", "de3c4beb"], "d": ["Dinastia rubenide, që mbante Adanën dhe Tarsusin, mori titullin mbretëror; është ndryshim titulli i së njëjtës dinasti, toka nuk ndërroi dorë. Dita e kurorëzimit NUK U GJET në TDV — data u mor nga fillimi i regjistrit të Mbretërisë Armene të Kilikisë (dita e regjistrit nuk është burim).", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["U themelua Perandoria Greke e Trapezundës — edhe Giresuni dhe Sinopi brenda kufijve", "a99b6ba0"], "d": ["Aleks Komneni, që për shkak të marrjes së Stambollit nga latinët iku në Trapezundë, u shpall perandor; qyteti u bë qendra e shtetit të ri. Shteti i themeluar nga nipërit Komnenë, Aleksi dhe Davidi, u shtri deri në Sinop; edhe Giresuni mbeti brenda kufijve të Perandorisë Greke të Trapezundës.", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["Kytahja nën sundimin e Perandorisë së Nikesë (Laskaris) — dëshmia e datuar në burim", "d91fa405"], "d": ["Burimi e tregon qytetin e Kytahjas në këtë datë nën administratën e Perandorisë së Nikesë (Laskaris); zotërimi më i hershëm nuk është i datuar në burim (atlasi e lë bosh periudhën para kësaj date).", "50f100b1"]},
"OLAYLAR_T5_1000A:1205-01-01:0":{"b": ["Ildenizidi Ebu Bekri mori Maragën", "03faed10"], "d": ["Ahmedilidi Alaeddin Kërpearslani u detyrua t'ia linte kështjellën e Maragës atabegut ildenizid Ebu Bekrit.", "742aae78"]},
"OLAYLAR_T5_1000A:1206-01-01:0":{"b": ["Selxhukët pushtuan Denizlinë dhe Honazin", "1053ccc8"], "d": ["Në sundimin e dytë të Gijaseddin Kejhusrevit I, Denizli dhe Honazi u kaluan selxhukëve (burimet bizantine thonë 1196, zëri selxhukë 603/1207).", "c102dae3"]},
"OLAYLAR_T5_1000A:1208-07-16:0":{"b": ["Gijaseddin Kejhusrevi I e bashkoi sërish Marashin me selxhukët", "91b1544e"], "d": ["Kejhusrevi organizoi fushatë kundër armenëve dhe e bashkoi Marashin me tokat selxhuke.", "5ffaa2f3"]},
"OLAYLAR_T5_1000A:1211-01-01:0":{"b": ["Kastamonu nën sundimin e Çobanidëve — dëshmia e datuar në burim", "10b682ba"], "d": ["Burimi e tregon qytetin e Kastamonusë në këtë datë nën administratën e Çobanidëve; zotërimi më i hershëm nuk është i datuar në burim (atlasi e lë bosh periudhën para kësaj date).", "1cdb9e90"]},
"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["Izzeddin Kejkavusi I pushtoi Sinopin", "463ea2b9"], "d": ["Sulltani selxhuk Izzeddin Kejkavusi I ua mori Sinopin Komnenëve të Trapezundës.", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["Alaeddin Kejkubadi I mori Kalonoros-in (Alaijen)", "5a4d6ac2"], "d": ["Kështjella Kalonoros, në lindje të Antalias, u mor nga selxhukët, u rindërtua dhe mori emrin Alaije (zëri alanya thotë 1221).", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Xhelaleddin Harzemshahu aneksoi Azerbajxhanin", "5b812b99"], "d": ["Xhelaleddin Harzemshahu e bashkoi Azerbajxhanin dhe Arranin me tokat e veta (fjali rajonale).", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Xhelaleddin Harzemshahu mori Maragën", "a55ec004"], "d": ["Xhelaleddin Harzemshahu pushtoi Maragën dhe e bëri qendrën e vet ushtarake dhe administrative në Azerbajxhan.", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Xhelaleddin Harzemshahu hyri në Tabriz", "72904097"], "d": ["Kur atabegu Özbek u tërhoq në Gjanxhë, Xhelaleddin Harzemshahu hyri në Tabriz, u bë zot i qytetit dhe e bëri qendër.", "43ee9867"]},
"OLAYLAR_T5_1000A:1228-01-01:0":{"b": ["Alaeddin Kejkubadi mori Kemahun", "8c5aa655"], "d": ["Dega Kemah-Erzinxhan e Menguxhukidëve iu bashkua tokave selxhuke nga Alaeddin Kejkubadi I, që rrethoi dhe mori Kemahun.", "7edb7223"]},
"OLAYLAR_T5_1000A:1231-01-01:0":{"b": ["Maraga u pushtua për herë të dytë nga mongolët", "f1320e5d"], "d": ["Në fund të sundimit harzemshah, Maraga kaloi në duart e mongolëve.", "9cee2a89"]},
"OLAYLAR_T5_1000A:1231-01-01:1":{"b": ["Azerbajxhani hyri nën sundimin mongol — Tabrizi u pushtua nga mongolët", "3f38ef66"], "d": ["Me rënien e Xhelaleddin Harzemshahut, Tabrizi u pushtua nga mongolët në 1231; sundimi mongol po atë vit përfshiu Azerbajxhanin Verior dhe Jugor (fjali rajonale, jo specifike për qytetin). Në Shirvan (Baku, Shamahi) Shirvanshahët vazhduan të ekzistonin si dinasti vendore nën sovranitetin mongol; atlasi i mban këto dy pika, me vendim të Emre-s, me ngjyrën shirvanshahe (vartësia mongole/ilhanide në shënim).", "46225c2e"]},
"OLAYLAR_T5_1000A:1232-10-01:0":{"b": ["Ajubidi el-Melikul-Kamil mori Amidin", "9cebe681"], "d": ["El-Melikul-Kamil rrethoi Amidin dhe ua mori Artukidëve.", "02085ee1"]},
"OLAYLAR_T5_1000A:1233-01-01:0":{"b": ["Alaeddin Kejkubadi I ia mori Kytahjan Perandorisë së Nikesë", "e0b9a7f7"], "d": ["Kytahja, që gjatë trazirave pas 1182 i kishte kaluar sërish Bizantit, u rimor nga Perandoria e Nikesë në kohën e Alaeddin Kejkubadit I.", "90db8b27"]},
"OLAYLAR_T5_1000A:1233-01-01:1":{"b": ["Bedreddin Lulu sulltan i Mosulit", "73268628"], "d": ["Me vdekjen e atabegut të fundit zengid, Bedreddin Lulu u shpall sulltan nga kalifi. (Rebiulevel 631 / dhjetor 1233; atlasi, duke ndjekur regjistrin, e shkruan me saktësi viti.)", "076b23b0"]},
"OLAYLAR_T5_1000A:1234-08-01:0":{"b": ["Selxhukët morën Harputin", "3b9391eb"], "d": ["Ushtria e Alaeddin Kejkubadit, me një rrethim njëzet e katër ditor, e mori në dorëzim kështjellën e Harputit; Artukidët e Harputit morën fund.", "1ae6c0d9"]},
"OLAYLAR_T5_1000A:1240-07-23:0":{"b": ["Gijaseddin Kejhusrevi II pushtoi Amidin", "c37c3b04"], "d": ["Sulltani selxhuk i Anadollit Gijaseddin Kejhusrevi II ua mori Amidin Ajubidëve.", "f8a0cc8c"]},
"OLAYLAR_T5_1000A:1253-01-01:0":{"b": ["Mëngke Kagani emëroi Iftiharuddinin guvernator të Kazvinit", "fc650d13"], "d": ["Hani i Madh mongol Mëngke emëroi guvernator në Kazvin; filloi periudha e Iftiharidëve.", "c042dadd"]},
"OLAYLAR_T5_1000A:1256-01-01:0":{"b": ["Ardhja e Hylagut: Kazvini dhe Nahçivani kaluan nën administratën ilhanide", "24673608"], "d": ["Me ardhjen e Hylagut në Iran, administrata mongole kaloi te Shteti Ilhanid; Kazvini dhe Nahçivani kaluan nën administratën ilhanide (kufiri i rregullit 5, jo dita e burimit). Në Shirvan (Baku, Shamahi) pushtimi mongol solli shkatërrime të rënda, por Shirvanshahët vazhduan si dinasti vendore; atlasi i mban këto dy pika me ngjyrën shirvanshahe (vendim i Emre-s).", "14d75e4f"]},
"OLAYLAR_T5_1000A:1257-01-01:0":{"b": ["Mongolët pushtuan Tikritin", "60af2df0"], "d": ["Gjatë pushtimit mongol Tikriti u pushtua dhe u plaçkit; qyteti doli nga administrata abaside.", "1a51fdd7"]},
"OLAYLAR_T5_1000A:1257-03-27:0":{"b": ["Hylagu marshoi nga Hamadani mbi Bagdad", "5f0c77b5"], "d": ["Hylagu u nis në fushatën e Bagdadit nga Hamadani, ku ndodheshin ngarkesat e rënda (dëshmi e sundimit ilhanid).", "303cbae8"]},
"OLAYLAR_T5_1000A:1258-01-01:0":{"b": ["Bogatimuri mori Kufën dhe Basrën", "dec82b4e"], "d": ["Forcat mongole nën komandën e Bogatimurit pushtuan Kufën, Vasitin dhe Basrën.", "10fd1496"]},
"OLAYLAR_T5_1000A:1258-01-01:1":{"b": ["Iraku kaloi në duart e mongolëve (rajonale)", "7b990281"], "d": ["Me pushtimin e Bagdadit nga Hylagu në 1258 u rrëzua Shteti Abasid dhe Iraku kaloi në duart e mongolëve.", "6f12d882"]},
"OLAYLAR_T5_1000A:1258-01-01:2":{"b": ["Marashi iu la armenëve", "6161f1a5"], "d": ["Imaduddini nga familja e Husameddinit, që nuk gjeti mbështetje, ua la Marashin armenëve të Kilikisë.", "9ea1e7ff"]},
"OLAYLAR_T5_1000A:1258-01-01:3":{"b": ["Vasiti kaloi nën sundimin ilhanid", "fbdf83fc"], "d": ["Me pushtimin e Irakut nga Ilhanidët, Vasiti hyri nën administratën e tyre.", "5f4aee6b"]},
"OLAYLAR_T5_1000A:1258-02-10:0":{"b": ["Mongolët morën Bagdadin; fundi i kalifatit abasid", "41c34bd4"], "d": ["Mongolët nën komandën e Hylagut sulmuan Bagdadin, kalifi Musta‘sim u dorëzua; qyteti kaloi nën sundimin ilhanid.", "1c979d91"]},
"OLAYLAR_T5_1000A:1262-01-01:0":{"b": ["Mongolët morën Mosulin, dinastia e Lulusë mori fund", "035d0121"], "d": ["Mosuli i el-Meliku's-Salih Ismailit, që mori anën e Bajbarsit, pësoi shkatërrimin mongol, dhe ai vetë u vra në prani të Hylagut.", "69cc41a9"]},
"OLAYLAR_T5_1000B:1069-10-20:0":{"b": ["Hutbja në Mekë u kthye nga Fatimidët në emër të kalifit abasid dhe të sulltan Alparslanit", "df951887"], "d": ["Meqë për shkak të urisë në Egjipt nuk erdhën furnizimet, emiri i Mekës Ebu Hashim Muhamed b. Xha‘fer e lexoi hutbën në emër të kalifit abasid Kaim-Bi-emrillah dhe sulltanit selxhuk Alparslan; Meka kaloi nën sovranitetin e Selxhukëve të Mëdhenj.", "c8a5b1f7"]},
"OLAYLAR_T5_1000B:1075-01-01:0":{"b": ["Atsiz b. Uvaku mori Damaskun", "8eea047f"], "d": ["Atsizi pushtoi Sirinë dhe e lexoi hutbën në emër të kalifit abasid dhe Melikshahut.", "1de51f0c"]},
"OLAYLAR_T5_1000B:1076-01-01:0":{"b": ["Emiri i Mekës Ebu Hashim e lexoi sërish hutbën në emër të kalifit fatimid", "85b6c0c0"], "d": ["Megjithë përpjekjet e Melikshahut për të forcuar ndikimin sunit, emiri i Mekës filloi ta lexonte sërish hutbën në emër të Fatimidëve; Meka u kthye nën sovranitetin fatimid.", "a7ec64c5"]},
"OLAYLAR_T5_1000B:1079-01-01:0":{"b": ["Tutushi hyri në Damask, u themeluan Selxhukët e Sirisë", "b48b38be"], "d": ["Tutushi hyri në qytet dhe themeloi Shtetin Selxhuk të Sirisë.", "6404e098"]},
"OLAYLAR_T5_1000B:1080-01-01:0":{"b": ["Emiri i Mekës njoftoi besnikërinë ndaj kalifit abasid Muktedi dhe sulltan Melikshahut", "38a430a5"], "d": ["Emiri i Mekës u bë sërish vartës i kalifit abasid dhe sulltanit selxhuk; kjo vartësi vazhdoi deri në vdekjen e Melikshahut (1092).", "41ad14e9"]},
"OLAYLAR_T5_1000B:1092-01-01:0":{"b": ["Me vdekjen e sulltan Melikshahut, hutbja në Mekë u kthye sërish te Fatimidët", "195a27cd"], "d": ["Kur vdiq sulltani selxhuk Melikshah, emiri i Mekës filloi t'i lexonte sërish hutbet në emër të kalifit fatimid; Meka kaloi nën sovranitetin fatimid.", "00e9a74b"]},
"OLAYLAR_T5_1000B:1097-07-01:0":{"b": ["Pas disfatës në Dorilaion, Eskishehiri u kthye te Bizanti", "3f381ee4"], "d": ["Pas tërheqjes së Kilixharslanit I përballë kryqtarëve, qyteti hyri sërish nën administratën bizantine.", "f3155b07"]},
"OLAYLAR_T5_1000B:1104-06-06:0":{"b": ["Tugtegini themeloi Atabegatin e Damaskut", "f26729c0"], "d": ["Pas vdekjes së Dukakut, atabegu Tugtegin themeloi dinastinë Borid.", "ac9e7419"]},
"OLAYLAR_T5_1000B:1150-01-01:0":{"b": ["Almohadët morën Meknesin", "ee976b41"], "d": ["Pas një rezistence të gjatë, qyteti hyri nën sundimin almohad dhe u plaçkit.", "4924b727"]},
"OLAYLAR_T5_1000B:1154-04-25:0":{"b": ["Nureddin Zengiu mori Damaskun", "a4fd8b58"], "d": ["Nureddin Mahmudi e vuri Damaskun nën sundimin e vet.", "f87fe7de"]},
"OLAYLAR_T5_1000B:1171-09-13:0":{"b": ["Në Egjipt mori fund administrata fatimide, erdhën në pushtet Ajubidët — Aleksandria, Fajumi dhe Meka (Hixhazi)", "1c565534"], "d": ["Me vezirllëkun e Selahudinit dhe vdekjen e kalifit fatimid Adid (567/1171), Egjipti u kaloi Ajubidëve; Aleksandria dhe Fajumi hynë nën administratën ajubide. Dita mungon te burimi — u mor nga fundi i regjistrit fatimid (dita e regjistrit nuk është burim). Edhe Hixhazi hyri nën administratën ajubide; sovraniteti mbi Mekën kaloi nga Fatimidët te Ajubidët (modeli i sovranit Emre #23).", "191ac5be"]},
"OLAYLAR_T5_1000B:1174-01-01:0":{"b": ["Selahudini mori Damaskun", "dfdb11ce"], "d": ["Pas vdekjes së Nureddinit, qyteti i kaloi Selahudin Ajubit.", "a20855b8"]},
"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["Pas Miriokefalonit, Bizanti zbrazi Dorilaionin", "24aef255"], "d": ["Pas disfatës së Miriokefalonit, Manueli, sipas traktatit, shkatërroi fortifikimin e Dorilaionit dhe e zbrazi qytetin; turqit filluan ta quajnë këtë vend Eskishehir.", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Amasja iu bashkua tokave selxhuke", "cf56b964"], "d": ["Kilixharslani II i bashkoi tokat danishmendide (përfshirë Amasjan) me vendin selxhuk.", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["Vëllezërit Asen morën Bullgarinë Veriore; Bizanti njohu Shtetin II Bullgar", "ff0554e9"], "d": ["Vëllezërit Petër dhe Asen, me mbështetjen kumane, rimorën Bullgarinë Veriore; me paqen e 1187, Bizanti njohu Shtetin II Bullgar.", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["Serbia e përforcoi sundimin në Zetë", "794c821d"], "d": ["Në 1189 Serbia e përforcoi sundimin mbi Zetën (përfshirë bregdetin e Kotorit); Zetës iu njoh status i veçantë.", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["Guy de Lusignan bleu Qipron, Nikosia u bë kryeqytet", "11017aea"], "d": ["Guy de Lusignan e bleu ishullin nga Templarët dhe e bëri Nikosian kryeqytet.", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["Kalojani pushtoi Varnën", "1237fe7f"], "d": ["Bullgarët nën komandën e carit Kalojan ia morën Varnën Bizantit në mars 1201; qyteti mbeti brenda kufijve të Shtetit Bullgar në shekujt XIII-XIV.", "b60444f8"]},
"OLAYLAR_T5_1000B:1202-01-01:0":{"b": ["Nishapuri iu bashkua përfundimisht Harzemshahëve", "fa4a6cd2"], "d": ["Alaeddin Muhamed b. Tekishi e bashkoi përfundimisht qytetin me tokat harzemshahe.", "58cb9059"]},
"OLAYLAR_T5_1000B:1204-04-13:0":{"b": ["Gadishulli i Galipolit hyri nën administratën latine", "27308f59"], "d": ["Pas Kryqëzatës IV, Galipoli dhe rrethina e tij kaluan në 1204 nën administratën latine.", "48b977ad"]},
"OLAYLAR_T5_1000B:1204-04-13:1":{"b": ["U themelua Despotati i Epirit — Janina u bë qendër, Lepanto i kaloi despotatit", "d7966877"], "d": ["Pas Kryqëzatës IV, Mihal Angeli themeloi Despotatin e Epirit; Janina u bë qendra e despotatit, edhe Lepanto mbeti brenda tokave të despotatit.", "632eac4c"]},
"OLAYLAR_T5_1000B:1204-08-12:0":{"b": ["Kreta iu shit Venedikut", "f1760e84"], "d": ["Markezi i Monferratit Bonifaci, me marrëveshjen e 12 gushtit 1204, ia la Kretën Venedikut për 100.000 argjend.", "cdb2570d"]},
"OLAYLAR_T5_1000B:1219-01-01:0":{"b": ["U themelua Mansura", "342a6f47"], "d": ["El-Melikul-Kamil themeloi Mansurën si selinë e komandës kundër kryqtarëve që pushtuan Damiettën.", "35189819"]},
"OLAYLAR_T5_1000B:1221-04-10:0":{"b": ["Mongolët morën Nishapurin", "0e73f075"], "d": ["Qyteti u shkatërrua nga pushtimi mongol.", "be55c768"]},
"OLAYLAR_T5_1000B:1229-01-01:0":{"b": ["Rasulidi Nureddin Omar e vuri Jemenin nën administratën e vet", "ee1ec7ab"], "d": ["Pas vdekjes së ajubidit të fundit të Jemenit, el-Mes‘udit, Nureddin Omari u bë zot i Jemenit.", "02cf9719"]},
"OLAYLAR_T5_1000B:1235-01-01:0":{"b": ["Perandori i Nikesë Vataci rimori Galipolin", "a6936e33"], "d": ["Perandori i Nikesë Joan III Duka Vataci ua rimori latinëve Galipolin (1235).", "184a089e"]},
"OLAYLAR_T5_1000B:1243-07-01:0":{"b": ["Mongolët pushtuan Amasjan", "783bcd0c"], "d": ["Pas Kösedagit, mongolët morën qytetin; atë e qeverisën guvernatorë mongolë.", "4e46e2df"]},
"OLAYLAR_T5_1000B:1246-01-01:0":{"b": ["Vataci kaloi në Trakë: Edreneja dhe Selaniku iu bashkuan Perandorisë së Nikesë", "0bf61ca5"], "d": ["Sundimtari i Nikesë Joan III Vataci kaloi në 1246 në Trakë dhe pushtoi tokat e zëna nga bullgarët dhe Selanikun.", "73992921"]},
"OLAYLAR_T5_1000B:1250-01-01:0":{"b": ["Sundimi rasulid njihej në Mekë — Nureddin Omari ra viktimë e një atentati", "d7e03c21"], "d": ["Kur sulltani rasulid i Jemenit Nureddin Omar u vra në Xhened (shkurt 1250), sundimi i shtetit të tij njihej midis Mekës dhe Hadramautit; në vitin kur mori fund sulltanati ajubid, Meka shfaqet nën sovranitetin rasulid.", "ba654624"]},
"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["U themelua në Egjipt Shteti Memluk — Aleksandria, Mansura dhe Fajumi u kaluan memlukëve", "230c1a11"], "d": ["Pas Turan Shahut, me Shexhererrdurr-in dhe Izzeddin Ajbekun u vendos pushteti memluk; qytetet egjiptiane (Aleksandri, Mansurë, Fajum) kaluan nën administratën memluke. Burimi jep hipjen në fron të Ajbekut më 3 korrik 1250; atlasi e mori ditën nga fundi i regjistrit ajubid (30 prill 1250) — dita e regjistrit nuk është burim, ndryshimi u njoftua.", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["Ajubidi i Halepit En-Nasir Jusuf u bë zot i Damaskut", "d585985d"], "d": ["Ndërsa në Egjipt vendosej pushteti memluk, sundimtari i Halepit En-Nasir Jusuf mori Damaskun (648/1250).", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["Jerusalemi iu la memlukëve me paqe", "50d53fac"], "d": ["Me paqen e bërë me ndërmjetësimin e kalifit, Jerusalemi iu la memlukëve.", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["Jerusalemi u kaloi sërish Ajubidëve", "fdeedd4a"], "d": ["Palestina dhe Jerusalemi kaluan sërish në duart e Ajubidëve të Sirisë.", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["Mongolët morën Damaskun", "430bdfea"], "d": ["Gjatë fushatës siriane të Hylagut, Damasku u kaloi mongolëve.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["Beteja e Ajn Xhalutit: Damasku dhe Jerusalemi u kaluan memlukëve", "40ebd7b7"], "d": ["Kutuzi mundi mongolët në Ajn Xhalut (25 ramazan 658 / 3 shtator 1260); pjesa më e madhe e Sirisë, Damasku dhe Jerusalemi kaluan në duart e memlukëve, dinastia ajubide mori fund.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Bajbarsi e ringjalli kalifatin abasid në Kajro — Meka dhe Medina u lidhën me memlukët", "a5128a1e"], "d": ["Bajbarsi e shpalli kalif në Kajro abasidin Ahmed, që shpëtoi nga shkatërrimi i Bagdadit, dhe i bëri bejat; si mbrojtës i kalifatit, edhe Haramejnin e lidhi nën sovranitetin memluk. Dita i përket ringjalljes së kalifatit; dita e lidhjes së Mekës dhe Medinës mungon te burimi (kufiri i poshtëm).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["Njësitë e Nikesë hynë në Stamboll — Perandoria Bizantine u rithemelua", "81741490"], "d": ["Njësitë e Nikesë hynë në Stamboll më 25 korrik 1261 dhe i dhanë fund sundimit latin; tokat e shtetit Laskarid (Nikesë) — Bursë, Izmir, Çimpë, Edrene, Selanik — u bënë sërish Perandori Bizantine. Në këto pika atlasi e tregon periudhën e Perandorisë së Nikesë para 1261 vetëm te ato që përmenden me emër në burim.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Charles d'Anjou mori Durrësin dhe Krujën", "082a86b8"], "d": ["Charles nga dinastia Anzhu në 1271-1272 mori Durrësin dhe Krujën dhe rindërtoi kështjellën e vjetër.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["Siçilianët pushtuan ishullin e Xherbës", "daab5ad2"], "d": ["Ishulli i Xherbës u pushtua nga siçilianët në vitin 683 (1284-85); fillimisht u bë pronë e papatit, më pas e lidhur me Mbretërinë e Sicilisë.", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Janina iu bashkua sërish Perandorisë Bizantine", "60016303"], "d": ["Janina, që në gjysmën e dytë të shekullit XIII ndërroi dorë shumë herë, iu bashkua sërish Bizantit në 1318, por ruajti deri diku autonominë; qendra e Despotatit të Epirit u zhvendos në Artë.", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["Banorët e Xherbës i dëbuan siçilianët nga ishulli", "ff71985e"], "d": ["Banorët e ishullit, që u ngritën kundër keqqeverisjes së guvernatorëve të Sicilisë, i dëbuan siçilianët në 1334; Xherba hyri sërish nën administratën hafside.", "1ddb9780"]},
"OLAYLAR_T5_1000B:1363-01-01:0":{"b": ["Karl Topia u bë zot i Krujës", "4e40583d"], "d": ["Pas vdekjes së carit Dushan (1355), shqiptari Karl Topia u bë zot i Krujës.", "7af64cd2"]},
"OLAYLAR_UMIT19_ASIRET_1119:1722-04-05:0":{"b": ["Roggeveen pa Ishullin e Pashkëve dhe e quajti Paasch Eyland; se në ishull jetonin njerëz u kuptua të nesërmen nga tymrat", "c6940261"], "d": ["Ekspedita e Jacob Roggeveen-it, sipas ditarit zyrtar të lundrimit, më 5 prill 1722 pa një ishull të ulët e të sheshtë dhe, meqë e gjeti në ditën e Pashkëve, e quajti Paasch Eyland. Më 6 prill u panë tymra që ngriheshin nga vende të ndryshme dhe u arrit në përfundimin se në ishull jetonin njerëz; tregimi i Behrens-it e vendos zbulimin më 6 prill.", "32641f88"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-08-13:0":{"b": ["Njësitë pararojë të ekspeditës së Sullivanit dogjën fshatin Chemung (Chemong)", "2656fcd6"], "d": ["Ushtria e Sullivanit në mbrëmjen e 12 gushtit 1779 u nis nga Tioga në marshim nate dhe në agimin e ditës tjetër mbërriti në fshatin Chemung; banorët kishin ikur më parë. Njësitë dogjën rreth njëzet ndërtesa të fshatit dhe shkatërruan arat me misër përreth.", "07caaa80"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-08-29:0":{"b": ["Beteja e Newtown-it: ekspedita e Sullivanit shpërndau llogoren pranë Chemung-ut të luftëtarëve irokezë, ku përfshiheshin edhe Cayuga dhe Seneca", "2383ea65"], "d": ["Ushtria e gjeneral-majorit Sullivan më 29 gusht 1779 pranë Chemung-ut u përball me llogoren e përgatitur nga forca ku, sipas letrës së Sullivanit, mbizotëronin luftëtarët indianë të «shtatë kombeve» (bashkë me Butler-at, Brant-in dhe McDonald-in, me komanda të veçanta); nga zjarri i artilerisë dhe presioni anësor i gjeneralit Poor, llogorja u braktis.", "3adfc9de"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-02:0":{"b": ["Ushtria e Sullivanit shkatërroi fshatin Catharine's Town dhe misrin e tij", "62b91293"], "d": ["Ushtria e ekspeditës së Sullivanit mbërriti natën e 1 shtatorit 1779 në Catharine's Town pranë liqenit Seneca; më 2 shtator shkatërroi fshatin dhe misrin e mbjellë. Fshati ishte vendbanim me tridhjetë shtëpi, me kopshte dhe me shumë misër.", "d56e8155"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-05:0":{"b": ["Ushtria e Sullivanit hyri në fshatin Kendaia; rreth njëzet shtëpi u bënë hi, të mbjellat dhe pemët frutore u shkatërruan", "68c01d89"], "d": ["Ushtria e Sullivanit mbërriti në fshatin Kendaia më 5 shtator 1779; sipas raportit të Sullivanit, fshati ishte braktisur. Ditari i Rogers-it shkruan se fshati u shkatërrua, ndërsa raporti zyrtar i Sullivanit shkruan se rreth njëzet shtëpi u bënë hi dhe se ushtria për rreth një ditë shkatërroi të mbjellat dhe pemët frutore.", "f29f4983"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-15:0":{"b": ["Ushtria e Sullivanit shkatërroi Genesee (Chenesee) Town dhe të mbjellat me misër e fasule", "c5e8f3be"], "d": ["Ushtria e Sullivanit më 14 shtator 1779 hyri në Genesee (Chenesee) Town me rreth shtatëdhjetë shtëpi; më 15 shtator e gjithë ushtria doli në terren për të shkatërruar të mbjellat, misri e fasulet u dogjën dhe, kur nisi marshimi i kthimit, fshatrat u lanë në flakë.", "3a04a429"]},
"OLAYLAR_UMIT19_ASIRET_1119:1830-10-07:0":{"b": ["Në Van Diemen's Land nisi operacioni Vija e Zezë (Black Line): kolonizatorët u mobilizuan për të kapur aborigjenët e Tasmanisë", "d2ffdfcb"], "d": ["Njoftimi i Sekretarisë Koloniale i guvernatorit Arthur, i datës 25 shtator 1830, shpalli se populli do të vepronte masivisht më 7 tetor 1830 dhe se majori Douglas po atë ditë do të mbante pikat e vëzhgimit përgjatë vijës. Qëllimi ishte kapja e fiseve aborigjene dhe shtyrja e tyre drejt Gadishullit Tasman.", "a7114cb5"]},
"OLAYLAR_UMIT19_ASIRET_1119:1830-11-26:0":{"b": ["Seria e parë e operacionit Vija e Zezë përfundoi zyrtarisht: Urdhri Qeveritar Nr. 13", "861ffa50"], "d": ["Urdhri Qeveritar Nr. 13 i datës 26 nëntor 1830 njoftoi se seria e parë e operacioneve për kapjen e fiseve vendase u mbyll me mbërritjen e njësive ushtarake e civile në East Bay Neck.", "a4f38ca9"]},
"OLAYLAR_UMIT19_ASIRET_1119:1850-07-18:0":{"b": ["Ekspedita Richardson–Barth–Overweg mbërriti në Gat (Ghat), ndalesa e dytë e madhe në rrugën e Saharasë pas Murzukut", "f52b2fa6"], "d": ["Heinrich Barth, duke kaluar Saharanë me ekspeditën e qeverisë britanike të kryesuar nga Richardson, në shënimin e ditarit të 18 korrikut 1850 tregon afrimin dhe mbërritjen në Gat (Ghat), që ai e konsideron ndalesën e dytë të madhe të ekspeditës; disa nga banorët e njohën dhe e pritën Richardson-in, i cili e kishte vizituar këtë vend edhe më parë. Kjo nuk është vizita e parë evropiane e rajonit.", "2e9bb2a4"]},
"OLAYLAR_UMIT19_ASIRET_1119:1869-07-13:0":{"b": ["Gustav Nachtigal mbërriti në Tao (Täo), njërën nga luginat kryesore të Tibestit", "bc67c7f0"], "d": ["Gustav Nachtigal, me karvanin e ardhur nga Murzuku, përparoi në rrëzën jugperëndimore të malësisë së Tibestit; në librin e tij Sahara dhe Sudani tregon mbërritjen më 13 korrik në luginën Tao, që e përshkruan si njërën nga luginat kryesore të Tibestit dhe si vendbanimin e vërtetë të familjeve fisnike (kapitulli «Ankunft in Täo» i librit). Ai shkruan se në mëngjesin e po asaj dite hynë në fushën e shtretërve të lumenjve të Taos, pastaj u takuan me Galmën, të afërm të Bü Zeidit.", "f8941a27"]},
"OLAYLAR_UMIT19_ASIRET_1119:1874-05-06:0":{"b": ["Ernest Giles, në kujtim të shokut të humbur Alfred Gibson, e quajti «Gibson's Desert» shkretëtirën në perëndim të vargmalit Rawlinson", "7ad5e61f"], "d": ["Ekspedita e Ernest Giles-it në Australinë Perëndimore (e nisur në gusht 1873) nga vargmali Rawlinson hyri drejt perëndimit në shkretëtirë; shoku i tij Alfred Gibson humbi në këtë shkretëtirë me kalin e Giles-it. Në ditarin e 6 majit 1874 Giles shkruan se këtij rajoni midis vargmalit Rawlinson dhe burimit të ardhshëm të përhershëm të ujit i dha emrin «Gibson's Desert».", "58bd64e7"]},
"OLAYLAR_UMIT19_ASIRET_1119:1879-08-02:0":{"b": ["Ekspedita e Gerhard Rohlfs-it hyri në Taiserbo, skaji verior i arkipelagut të oazeve të Kufrës", "577b4205"], "d": ["Ekspedita e Gerhard Rohlfs-it për Shoqatën Gjermane të Afrikës, e nisur nga Tripoli, pas marrëveshjes me Suya-t në korrik 1879 marshoi drejt jugut dhe hyri në orën 2 të natës në oazën Taiserbo, ishulli më verior i Kufrës. Rohlfs e tregon këtë si «mbërritjen më në fund në oazën misterioze të Kufrës»; ndërsa te pusi Djrängedi mbërritën vetëm të nesërmen në orën 11 të mëngjesit.", "ca155f46"]},
"OLAYLAR_UMIT19_ASIRET_1119:1896-12-04:0":{"b": ["Ekspedita me deve e David Carnegie-t mbërriti në Halls Creek në Kimberley; takoi njeriun e parë të bardhë që nga 21 korriku", "55b94bf8"], "d": ["Ekspedita me deve e David Carnegie-t, e nisur nga Coolgardie më 9 korrik 1896, mbërriti në Halls Creek më 4 dhjetor. Carnegie shkruan se njeriu i parë që takuan ishte rreshteri i policisë Brophy dhe se që nga 21 korriku nuk kishin parë asnjë fytyrë të bardhë; udhëtimi, përfshirë devijimet, kishte zgjatur 1.413 milje.", "82b25b9d"]}
});
